import React, { useState, useEffect } from 'react';
import {
    Popover,
    Box,
    Typography,
    RadioGroup,
    FormControlLabel,
    Radio,
    TextField,
    Button,
    Divider
} from '@mui/material';

const OPTIONS = [
    { label: '3 000 pts', value: 3000 },
    { label: '3 500 pts', value: 3500 },
    { label: '4 000 pts', value: 4000 },
    { label: 'Sans limite', value: null },
    { label: 'Personnalisé', value: 'custom' },
];

function LimitePtsPopover({ anchorEl, open, onClose, limitePts, onConfirm }) {
    const isCustom = limitePts !== null && !OPTIONS.some(o => o.value === limitePts);
    const [selected, setSelected] = useState(isCustom ? 'custom' : String(limitePts));
    const [customValue, setCustomValue] = useState(isCustom ? String(limitePts) : '');

    useEffect(() => {
        if (open) {
            const isC = limitePts !== null && !OPTIONS.some(o => o.value === limitePts);
            setSelected(isC ? 'custom' : String(limitePts));
            setCustomValue(isC ? String(limitePts) : '');
        }
    }, [open, limitePts]);

    const handleConfirm = () => {
        if (selected === 'custom') {
            const val = parseInt(customValue);
            if (!isNaN(val) && val > 0) onConfirm(val);
        } else if (selected === 'null') {
            onConfirm(null);
        } else {
            onConfirm(parseInt(selected));
        }
        onClose();
    };

    return (
        <Popover
            open={open}
            anchorEl={anchorEl}
            onClose={onClose}
            anchorOrigin={{ vertical: 'bottom', horizontal: 'left' }}
            transformOrigin={{ vertical: 'top', horizontal: 'left' }}
        >
            <Box sx={{ p: 2, minWidth: 200 }}>
                <Typography variant="subtitle2" fontWeight="bold" gutterBottom>
                    Limite de points
                </Typography>
                <RadioGroup
                    value={selected}
                    onChange={(e) => setSelected(e.target.value)}
                >
                    {OPTIONS.map(opt => (
                        <FormControlLabel
                            key={String(opt.value)}
                            value={String(opt.value)}
                            control={<Radio size="small" />}
                            label={opt.label}
                        />
                    ))}
                </RadioGroup>

                {selected === 'custom' && (
                    <TextField
                        type="number"
                        size="small"
                        fullWidth
                        label="Points"
                        value={customValue}
                        onChange={(e) => setCustomValue(e.target.value)}
                        inputProps={{ min: 500, step: 500 }}
                        sx={{ mt: 1 }}
                        autoFocus
                    />
                )}

                <Divider sx={{ my: 1.5 }} />
                <Button
                    variant="contained"
                    size="small"
                    fullWidth
                    onClick={handleConfirm}
                    disabled={selected === 'custom' && (!customValue || parseInt(customValue) <= 0)}
                >
                    Valider
                </Button>
            </Box>
        </Popover>
    );
}

export default LimitePtsPopover;
