import React, { useState, useEffect } from 'react';
import {
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Button,
    Box,
    Typography,
    RadioGroup,
    Radio,
    FormControlLabel,
    Chip,
    Divider,
    Table,
    TableBody,
    TableRow,
    TableCell
} from '@mui/material';
import caracData from '../data/stats/carac.json';

const trouverStats = (factionName, uniteName) => {
    if (!factionName || !uniteName) return null;
    const factionEntry = caracData.find(f => f.faction.toLowerCase() === factionName.toLowerCase());
    if (!factionEntry) return null;
    const stats = factionEntry.stat;
    let found = stats.find(s => s.Nom === uniteName);
    if (found) return found;
    const lower = uniteName.toLowerCase();
    found = stats.find(s => s.Nom.toLowerCase() === lower);
    if (found) return found;
    found = stats.find(s => s.Nom.toLowerCase().includes(lower) || lower.includes(s.Nom.toLowerCase()));
    return found || null;
};

function ChoixAmeliorationDialog({ open, onClose, amelioration, onConfirm, filteredChoix, faction }) {
    const [selectedChoix, setSelectedChoix] = useState('');

    useEffect(() => {
        if (open) setSelectedChoix('');
    }, [open]);

    if (!amelioration?.choix) return null;
    const choixToShow = filteredChoix || amelioration.choix;

    const handleConfirm = () => {
        if (!selectedChoix) return;
        const choixDef = amelioration.choix.find(c => c.name === selectedChoix);
        onConfirm(selectedChoix, choixDef?.name || selectedChoix);
        onClose();
    };

    const selectedDef = choixToShow.find(c => c.name === selectedChoix);
    const stats = selectedDef
        ? trouverStats(faction, selectedDef.unit_stat_name || selectedDef.name)
        : null;

    return (
        <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
            <DialogTitle>{amelioration.name}</DialogTitle>

            <DialogContent dividers>
                <Typography variant="body2" color="textSecondary" gutterBottom>
                    Choisissez un type :
                </Typography>

                <RadioGroup
                    value={selectedChoix}
                    onChange={(e) => setSelectedChoix(e.target.value)}
                >
                    {choixToShow.map(choix => (
                        <FormControlLabel
                            key={choix.name}
                            value={choix.name}
                            control={<Radio />}
                            label={
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                    <Typography variant="body1">{choix.name}</Typography>
                                    {choix.cout > 0 && (
                                        <Chip label={`+${choix.cout} pts`} size="small" variant="outlined" />
                                    )}
                                    {choix.cout === 0 && amelioration.cout > 0 && (
                                        <Chip label={`${amelioration.cout} pts`} size="small" variant="outlined" />
                                    )}
                                    {choix.limiteOptionGlobal && (
                                        <Chip label="0-1 armée" size="small" color="warning" variant="outlined" />
                                    )}
                                </Box>
                            }
                        />
                    ))}
                </RadioGroup>

                {stats && (
                    <>
                        <Divider sx={{ my: 1.5 }} />
                        <Typography variant="caption" color="textSecondary" sx={{ fontWeight: 'bold', textTransform: 'uppercase' }}>
                            {stats.Nom}
                        </Typography>
                        <Table size="small" sx={{ mt: 0.5 }}>
                            <TableBody>
                                <TableRow>
                                    {[
                                        ['Type', stats.Type],
                                        ['Vitesse', stats.Vitesse],
                                        ['Blind.', stats.Blindage],
                                        ['CC', stats.CC],
                                        ['FF', stats.FF],
                                    ].map(([label, val]) => (
                                        <TableCell key={label} sx={{ py: 0.5, px: 1, border: 'none' }}>
                                            <Typography variant="caption" color="textSecondary">{label}</Typography>
                                            <Typography variant="body2" fontWeight="bold">{val}</Typography>
                                        </TableCell>
                                    ))}
                                </TableRow>
                            </TableBody>
                        </Table>
                        {stats.armes?.length > 0 && (
                            <Box sx={{ mt: 0.5 }}>
                                {stats.armes.map((arme, i) => (
                                    <Typography key={i} variant="caption" display="block" color="textSecondary">
                                        <strong>{arme.Arme}</strong> {arme.Portée} — {arme['Puissance de feu']}
                                    </Typography>
                                ))}
                            </Box>
                        )}
                        {stats.Notes && (
                            <Typography variant="caption" display="block" color="textSecondary" sx={{ mt: 0.5, fontStyle: 'italic' }}>
                                {stats.Notes}
                            </Typography>
                        )}
                    </>
                )}
            </DialogContent>

            <DialogActions>
                <Button onClick={onClose}>Annuler</Button>
                <Button onClick={handleConfirm} variant="contained" disabled={!selectedChoix}>
                    Ajouter
                </Button>
            </DialogActions>
        </Dialog>
    );
}

export default ChoixAmeliorationDialog;
