import React, { useState } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Button,
  Box,
  Typography,
  Alert,
  Divider
} from '@mui/material';
import GoogleIcon from '@mui/icons-material/Google';
import { useAuth } from '../contexts/AuthContext';

function LoginDialog({ open, onClose }) {
  const { login, signup, loginWithGoogle, resetPassword } = useAuth();
  const [isSignup, setIsSignup] = useState(false);
  const [isReset, setIsReset] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');
    setLoading(true);

    try {
      if (isReset) {
        await resetPassword(email);
        setSuccess('Un email de réinitialisation a été envoyé si un compte existe avec cette adresse.');
      } else if (isSignup) {
        await signup(email, password);
        handleClose();
      } else {
        await login(email, password);
        handleClose();
      }
    } catch (err) {
      switch (err.code) {
        case 'auth/invalid-email':
          setError('Adresse email invalide.');
          break;
        case 'auth/user-not-found':
          setError('Aucun compte trouvé avec cet email.');
          break;
        case 'auth/wrong-password':
        case 'auth/invalid-credential':
          setError('Email ou mot de passe incorrect.');
          break;
        case 'auth/email-already-in-use':
          setError('Un compte existe déjà avec cet email.');
          break;
        case 'auth/weak-password':
          setError('Le mot de passe doit contenir au moins 6 caractères.');
          break;
        default:
          setError(err.message);
      }
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleLogin = async () => {
    setError('');
    setLoading(true);
    try {
      await loginWithGoogle();
      handleClose();
    } catch (err) {
      console.error('Google login error:', err.code, err.message);
      if (err.code !== 'auth/popup-closed-by-user') {
        setError(`Erreur lors de la connexion Google. (${err.code})`);
      }
    } finally {
      setLoading(false);
    }
  };

  const handleClose = () => {
    setEmail('');
    setPassword('');
    setError('');
    setSuccess('');
    setIsSignup(false);
    setIsReset(false);
    onClose();
  };

  const switchToReset = () => {
    setIsReset(true);
    setIsSignup(false);
    setError('');
    setSuccess('');
  };

  const switchToLogin = () => {
    setIsReset(false);
    setIsSignup(false);
    setError('');
    setSuccess('');
  };

  return (
    <Dialog open={open} onClose={handleClose} maxWidth="xs" fullWidth>
      <DialogTitle>
        {isReset ? 'Mot de passe oublié' : isSignup ? 'Créer un compte' : 'Se connecter'}
      </DialogTitle>

      <form onSubmit={handleSubmit}>
        <DialogContent>
          {error && (
            <Alert severity="error" sx={{ mb: 2 }}>
              {error}
            </Alert>
          )}

          {success && (
            <Alert severity="success" sx={{ mb: 2 }}>
              {success}
            </Alert>
          )}

          {isReset && !success && (
            <Typography variant="body2" color="textSecondary" sx={{ mb: 2 }}>
              Entrez votre adresse email pour recevoir un lien de réinitialisation de mot de passe.
            </Typography>
          )}

          <TextField
            label="Email"
            type="email"
            fullWidth
            required
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            sx={{ mb: 2 }}
            autoFocus
            disabled={!!success}
          />

          {!isReset && (
            <TextField
              label="Mot de passe"
              type="password"
              fullWidth
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              sx={{ mb: 2 }}
            />
          )}

          {!isReset && (
            <>
              <Divider sx={{ my: 2 }}>ou</Divider>

              <Button
                fullWidth
                variant="outlined"
                startIcon={<GoogleIcon />}
                onClick={handleGoogleLogin}
                disabled={loading}
              >
                Se connecter avec Google
              </Button>
            </>
          )}
        </DialogContent>

        <DialogActions sx={{ px: 3, pb: 2, flexDirection: 'column', gap: 1 }}>
          {!success && (
            <Button
              type="submit"
              variant="contained"
              fullWidth
              disabled={loading}
            >
              {isReset ? 'Envoyer le lien' : isSignup ? 'Créer un compte' : 'Se connecter'}
            </Button>
          )}

          {isReset ? (
            <Box sx={{ textAlign: 'center', width: '100%' }}>
              <Button size="small" onClick={switchToLogin}>
                Retour à la connexion
              </Button>
            </Box>
          ) : (
            <>
              <Box sx={{ textAlign: 'center', width: '100%' }}>
                <Typography variant="body2">
                  {isSignup ? 'Déjà un compte ?' : 'Pas encore de compte ?'}{' '}
                  <Button
                    size="small"
                    onClick={() => {
                      setIsSignup(!isSignup);
                      setError('');
                    }}
                  >
                    {isSignup ? 'Se connecter' : "S'inscrire"}
                  </Button>
                </Typography>
              </Box>

              {!isSignup && (
                <Box sx={{ textAlign: 'center', width: '100%' }}>
                  <Button size="small" onClick={switchToReset}>
                    Mot de passe oublié ?
                  </Button>
                </Box>
              )}
            </>
          )}
        </DialogActions>
      </form>
    </Dialog>
  );
}

export default LoginDialog;
