/**
 * Validations des dépendances et tags
 *
 * Algorithme de résolution des slots :
 * 1. Calcul de la capacité totale par tag (depuis FormationLimitationTag)
 * 2. Collecte des formations consommatrices triées par flexibilité croissante
 *    (formations mono-tag en premier, multi-tag en dernier)
 * 3. Backtracking pour trouver une assignation tag valide
 */
export class DependencyValidator {

    /**
     * Calcule la capacité totale disponible pour chaque tag
     * @returns {Object} ex: { A: 3, B: 6, C: 3 }
     */
    static calculerCapaciteSlots(liste, codex) {
        const capacite = {};
        liste.formations.forEach(formation => {
            const def = trouverFormation(codex, formation.formationId);
            if (!def?.FormationLimitationTag) return;
            Object.entries(def.FormationLimitationTag).forEach(([tag, slots]) => {
                capacite[tag] = (capacite[tag] || 0) + slots;
            });
        });
        return capacite;
    }

    /**
     * Collecte les formations qui consomment des slots avec leurs tags possibles
     * @returns {Array} [{ id, formationId, tags: ['A','B','C'] }, ...]
     */
    static collecterConsommateurs(liste, codex) {
        const consommateurs = [];
        liste.formations.forEach(formation => {
            for (const groupe of codex.groupes) {
                if (!groupe.LimitationTag) continue;
                if (groupe.formations.some(f => f.id === formation.formationId)) {
                    const tags = Array.isArray(groupe.LimitationTag)
                        ? groupe.LimitationTag
                        : [groupe.LimitationTag];
                    consommateurs.push({ id: formation.id, formationId: formation.formationId, tags });
                    break;
                }
            }
        });
        // Trier par flexibilité croissante : mono-tag d'abord, multi-tag en dernier
        consommateurs.sort((a, b) => a.tags.length - b.tags.length);
        return consommateurs;
    }

    /**
     * Résout l'assignation tags ↔ formations par backtracking.
     * @returns {Object|null} assignation { formationInstanceId → tag } ou null si impossible
     */
    static resoudreAssignation(consommateurs, capacite) {
        const assignation = {};
        const utilisation = Object.fromEntries(
            Object.keys(capacite).map(k => [k, 0])
        );

        function backtrack(index) {
            if (index === consommateurs.length) return true;
            const { id, tags } = consommateurs[index];

            for (const tag of tags) {
                const cap = capacite[tag] || 0;
                const util = utilisation[tag] || 0;
                if (util < cap) {
                    assignation[id] = tag;
                    utilisation[tag] = util + 1;
                    if (backtrack(index + 1)) return true;
                    delete assignation[id];
                    utilisation[tag] = util;
                }
            }
            return false;
        }

        return backtrack(0) ? assignation : null;
    }

    /**
     * Vérifie si la liste courante a une assignation de slots valide.
     * Utilisé par validateListe pour détecter les erreurs post-modification.
     */
    static validerAssignationGlobale(liste, codex) {
        const capacite = this.calculerCapaciteSlots(liste, codex);
        const consommateurs = this.collecterConsommateurs(liste, codex);
        if (consommateurs.length === 0) return { valid: true };

        const assignation = this.resoudreAssignation(consommateurs, capacite);
        if (assignation) return { valid: true, assignation };

        // Construire un message d'erreur lisible
        const tagsImpliques = [...new Set(consommateurs.flatMap(c => c.tags))];
        const details = tagsImpliques.map(tag => {
            const cap = capacite[tag] || 0;
            const demande = consommateurs.filter(c => c.tags.includes(tag)).length;
            return `Tag ${tag} : ${cap} slot(s) dispo, ${demande} formation(s) compatibles`;
        }).join(' | ');

        return {
            valid: false,
            error: `Slots insuffisants — ${details}`,
            type: 'LIMITATION_TAG',
            blocking: true
        };
    }

    /**
     * Vérifie si on PEUT ajouter une formation (simulation avec la nouvelle formation).
     * Retourne aussi le tag qui sera consommé.
     */
    static validateLimitationTag(liste, codex, formationDef) {
        // Trouver le groupe de la formation à ajouter
        let groupe = null;
        for (const g of codex.groupes) {
            if (g.formations.some(f => f.id === formationDef.id)) {
                groupe = g;
                break;
            }
        }

        const rawTag = groupe?.LimitationTag ?? formationDef.LimitationTag;
        if (!rawTag) return { valid: true };

        // Simuler l'ajout : créer une liste temporaire avec une fausse formation
        const fausseFormation = {
            id: '__temp_validation__',
            formationId: formationDef.id,
            slotTagUtilise: undefined
        };
        const listeSimulee = {
            ...liste,
            formations: [...liste.formations, fausseFormation]
        };

        const capacite = this.calculerCapaciteSlots(listeSimulee, codex);
        const consommateurs = this.collecterConsommateurs(listeSimulee, codex);

        const assignation = this.resoudreAssignation(consommateurs, capacite);

        if (!assignation) {
            const tags = Array.isArray(rawTag) ? rawTag : [rawTag];
            const details = tags.map(tag => {
                const cap = capacite[tag] || 0;
                const util = consommateurs.filter(c =>
                    Object.values(assignation || {}).filter((v, i) =>
                        consommateurs[i]?.tags.includes(tag)
                    ).length
                ).length;
                return `${tag}: ${cap} disponibles`;
            }).join(', ');

            return {
                valid: false,
                error: `Pas de slot disponible pour cette formation (${tags.join(' ou ')}) — ${details}`,
                type: 'LIMITATION_TAG'
            };
        }

        // Retourner le tag assigné à la fausse formation
        const slotTagUtilise = assignation['__temp_validation__'] || null;
        return { valid: true, slotTagUtilise };
    }

    /**
     * Vérifie la limite max_par_tag (nombre max de formations d'un groupe par "parent")
     */
    static validateMaxParTag(liste, codex, formationDef) {
        let groupe = null;
        for (const g of codex.groupes) {
            if (g.formations.some(f => f.id === formationDef.id)) {
                groupe = g;
                break;
            }
        }

        const rawTag = groupe?.LimitationTag ?? formationDef.LimitationTag;
        const maxParTag = groupe?.max_par_tag ?? formationDef.max_par_tag;
        if (!rawTag || !maxParTag) return { valid: true };

        const tags = Array.isArray(rawTag) ? rawTag : [rawTag];

        // Compter les formations existantes du même groupe
        let countMemeGroupe = 0;
        liste.formations.forEach(f => {
            if (groupe?.formations.some(fd => fd.id === f.formationId)) {
                countMemeGroupe++;
            }
        });

        // Calculer les slots totaux disponibles pour ce groupe
        const capacite = this.calculerCapaciteSlots(liste, codex);
        const slotsTotaux = tags.reduce((sum, tag) => sum + (capacite[tag] || 0), 0);

        if (countMemeGroupe >= maxParTag && countMemeGroupe >= slotsTotaux) {
            return {
                valid: false,
                error: `Maximum ${maxParTag} formations de ce type par cadre`,
                type: 'MAX_PAR_TAG'
            };
        }

        return { valid: true };
    }

    // ── Méthodes de compatibilité conservées pour l'UI ──────────────────────

    /**
     * Compte les slots disponibles pour un tag (pour l'affichage)
     */
    static countAvailableSlotsForTag(liste, codex, tag) {
        const capacite = this.calculerCapaciteSlots(liste, codex);
        return capacite[tag] || 0;
    }

    /**
     * Compte les formations utilisant un tag dans l'assignation optimale (pour l'affichage)
     */
    static countFormationsUsingTag(liste, codex, tag) {
        const consommateurs = this.collecterConsommateurs(liste, codex);
        const capacite = this.calculerCapaciteSlots(liste, codex);
        const assignation = this.resoudreAssignation(consommateurs, capacite);
        if (!assignation) return 0;
        return Object.values(assignation).filter(t => t === tag).length;
    }
}

function trouverFormation(codex, formationId) {
    for (const groupe of codex.groupes) {
        const formation = groupe.formations.find(f => f.id === formationId);
        if (formation) return formation;
    }
    return null;
}