import React, { useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import {
  BottomNavigation,
  BottomNavigationAction,
  Paper,
  AppBar,
  Toolbar,
  IconButton,
  Menu,
  MenuItem,
  Avatar,
  Typography,
  Box,
  Button
} from '@mui/material';
import HomeIcon from '@mui/icons-material/Home';
import ListAltIcon from '@mui/icons-material/ListAlt';
import MenuBookIcon from '@mui/icons-material/MenuBook';
import PreviewIcon from '@mui/icons-material/Preview';
import LoginIcon from '@mui/icons-material/Login';
import PlaylistAddIcon from '@mui/icons-material/PlaylistAdd';
import { useAuth } from '../../../contexts/AuthContext';
import LoginDialog from '../../../components/LoginDialog';

function BottomNav() {
  const navigate = useNavigate();
  const location = useLocation();
  const { user, logout } = useAuth();

  const [loginOpen, setLoginOpen] = useState(false);
  const [anchorEl, setAnchorEl] = useState(null);

  // Detect if we're on a builder route and extract codexId
  const builderMatch = location.pathname.match(/^\/builder\/([^/]+)/);
  const isOnBuilder = !!builderMatch;
  const currentCodexId = builderMatch ? builderMatch[1] : null;
  const isOnPreview = location.pathname.endsWith('/preview');

  // Mémoriser le dernier codexId actif pour garder les boutons Builder/Aperçu sur la page règles
  if (currentCodexId) sessionStorage.setItem('last_builder_codexId', currentCodexId);
  const lastCodexId = currentCodexId || sessionStorage.getItem('last_builder_codexId');
  const hasActiveBuilder = !!lastCodexId;
  const codexId = lastCodexId;

  const getActiveTab = () => {
    if (location.pathname === '/') return 'home';
    if (isOnPreview) return 'preview';
    if (location.pathname.startsWith('/builder') && !isOnPreview) return 'builder';
    if (location.pathname === '/mes-listes') return 'mes-listes';
    if (location.pathname === '/rules') return 'rules';
    return 'home';
  };

  const handleTabChange = (event, newValue) => {
    if (newValue === 'home') navigate('/');
    else if (newValue === 'mes-listes') navigate('/mes-listes');
    else if (newValue === 'builder') navigate(`/builder/${codexId}`);
    else if (newValue === 'preview') navigate(`/builder/${codexId}/preview`);
    else if (newValue === 'rules') navigate('/rules');
  };

  const handleLogout = async () => {
    setAnchorEl(null);
    try {
      await logout();
    } catch (err) {
      console.error('Erreur déconnexion:', err);
    }
  };

  return (
    <>
      {/* Top bar with login/profile */}
      <AppBar position="fixed" color="default" elevation={1} sx={{ top: 0 }}>
        <Toolbar sx={{ justifyContent: 'space-between', minHeight: 48 }}>
          {/* Logo cliquable → accueil */}
          <Box
            component="img"
            src={`${process.env.PUBLIC_URL}/assets/images/logo.png`}
            alt="Epic List Builder"
            onClick={() => navigate('/')}
            sx={{ height: 36, width: 'auto', objectFit: 'contain', cursor: 'pointer' }}
          />
          {user ? (
            <>
              <IconButton onClick={(e) => setAnchorEl(e.currentTarget)}>
                <Avatar
                  src={user.photoURL}
                  sx={{ width: 32, height: 32, bgcolor: 'primary.main' }}
                >
                  {user.email?.[0]?.toUpperCase()}
                </Avatar>
              </IconButton>
              <Menu
                anchorEl={anchorEl}
                open={Boolean(anchorEl)}
                onClose={() => setAnchorEl(null)}
              >
                <MenuItem disabled>
                  <Typography variant="body2">{user.email}</Typography>
                </MenuItem>
                <MenuItem onClick={handleLogout}>Déconnexion</MenuItem>
              </Menu>
            </>
          ) : (
            <Button
              variant="contained"
              size="small"
              startIcon={<LoginIcon />}
              onClick={() => setLoginOpen(true)}
              sx={{ fontWeight: 'bold', borderRadius: 2, textTransform: 'none' }}
            >
              Connexion
            </Button>
          )}
        </Toolbar>
      </AppBar>

      {/* Spacer for top bar */}
      <Box sx={{ height: 48 }} />

      {/* Bottom navigation */}
      <Paper
        className="bottom-nav-bar"
        sx={{ position: 'fixed', bottom: 0, left: 0, right: 0, zIndex: 1100 }}
        elevation={3}
      >
        <BottomNavigation
          value={getActiveTab()}
          onChange={handleTabChange}
          showLabels
        >
          <BottomNavigationAction value="home" label="Home" icon={<HomeIcon />} />
          <BottomNavigationAction value="mes-listes" label="Listes" icon={<ListAltIcon />} />
          {hasActiveBuilder && <BottomNavigationAction value="builder" label="Builder" icon={<PlaylistAddIcon />} />}
          {hasActiveBuilder && <BottomNavigationAction value="preview" label="Aperçu" icon={<PreviewIcon />} />}
          <BottomNavigationAction value="rules" label="Règles" icon={<MenuBookIcon />} />
        </BottomNavigation>
      </Paper>


      {/* Login dialog */}
      <LoginDialog open={loginOpen} onClose={() => setLoginOpen(false)} />
    </>
  );
}

export default BottomNav;