import React, { useState, useEffect } from 'react';
import {
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Button,
    Box,
    Typography,
    Alert,
    Slider,
    Chip
} from '@mui/material';

// configOverride : passe directement une config (pour composition_synaptique / composition_essaims)
// dialogTitle    : titre personnalisé quand configOverride est utilisé
function CompositionPersonnaliseeDialog({ open, onClose, formationDef, onConfirm, overrideTotal, configOverride, dialogTitle, capaciteTransportMap }) {
    const [composition, setComposition] = useState({});
    const [error, setError] = useState('');

    const config = configOverride || formationDef?.composition_personnalisee;

    useEffect(() => {
        if (open && config) {
            const init = {};
            config.options.forEach(opt => { init[opt.id] = opt.min || 0; });
            setComposition(init);
            setError('');
        }
    }, [open, config]);

    if (!config) return null;

    const total = Object.values(composition).reduce((sum, val) => sum + val, 0);

    const minTotal = overrideTotal || config.min_total || config.total || 0;
    const maxTotal = overrideTotal || config.max_total || config.total || 0;
    const groupeObligatoire = config.groupe_obligatoire || [];
    const groupeValid = groupeObligatoire.length === 0
        || groupeObligatoire.some(id => (composition[id] || 0) > 0);
    const isValid = total >= minTotal && total <= maxTotal && groupeValid;

    // Coût supplémentaire apporté par cette composition (options payantes)
    const coutAdditionnel = config.options.reduce((sum, opt) => {
        const count = composition[opt.id] || 0;
        if (count === 0) return sum;
        if (opt.cout_paliers) {
            const palier = opt.cout_paliers.find(p => p.value === count)
                || opt.cout_paliers.find(p => count <= p.max)
                || opt.cout_paliers[opt.cout_paliers.length - 1];
            return sum + (palier?.cout || 0);
        }
        return sum + (opt.cout || 0) * count;
    }, 0);

    const capaciteMap = capaciteTransportMap || {};
    const hasTransportOptions = config.options.some(opt => capaciteMap[opt.unitId]);
    const placesTransport = config.options.reduce((sum, opt) => {
        const cap = capaciteMap[opt.unitId];
        if (!cap) return sum;
        return sum + cap * (composition[opt.id] || 0) * (opt.nombre_par_slot || 1);
    }, 0);

    const isOptionBloquee = (optionId) =>
        config.options.some(opt => opt.exclusif_avec?.includes(optionId) && (composition[opt.id] || 0) > 0);

    const handleChange = (optionId, value) => {
        const numValue = typeof value === 'number' ? value : (parseInt(value) || 0);
        const option = config.options.find(o => o.id === optionId);
        const curVal = composition[optionId] || 0;
        const optionMax = overrideTotal ? Math.max(option.max, overrideTotal) : option.max;
        const effectiveMax = Math.min(optionMax, maxTotal - total + curVal);
        if (numValue !== 0 && option.valeurs_possibles && !option.valeurs_possibles.includes(numValue)) return;
        if (numValue < (option.min || 0) || numValue > effectiveMax) return;
        setComposition(prev => {
            const next = { ...prev, [optionId]: numValue };
            if (numValue > 0 && option.exclusif_avec) {
                option.exclusif_avec.forEach(excId => { next[excId] = 0; });
            }
            return next;
        });
    };

    const handleConfirm = () => {
        if (!isValid) {
            if (total < minTotal) {
                setError(`Vous devez sélectionner au moins ${minTotal} slot(s)`);
            } else {
                setError(`Vous ne pouvez pas sélectionner plus de ${maxTotal} slot(s)`);
            }
            return;
        }

        const unites = [];
        config.options.forEach(option => {
            const count = composition[option.id];
            if (count > 0) {
                const nombreFig = count * (option.nombre_par_slot || 1);
                unites.push({
                    id: genererID(),
                    uniteId: option.unitId,
                    nom: option.name,
                    nombre: nombreFig,
                    options: [],
                    ...(option.tags?.length && { tags: option.tags }),
                    ...(option.stat_nom && { stat_nom: option.stat_nom })
                });
            }
        });

        onConfirm(unites, coutAdditionnel);
        onClose();
    };

    function genererID() {
        return Date.now() + '_' + Math.random().toString(36).substr(2, 9);
    }

    const hasPaidOptions = config.options.some(o => (o.cout || 0) > 0 || o.cout_paliers);
    const title = dialogTitle || formationDef?.name || '';

    const formationDescription = formationDef?.description;

    return (
        <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
            <DialogTitle sx={{ pb: 0 }}>
                <Typography variant="h6">{title}</Typography>
                {formationDescription && (
                    <Typography variant="body2" color="textSecondary" sx={{ mt: 0.5 }}>
                        {formationDescription}
                    </Typography>
                )}
                {config.description && (
                    <Typography variant="body2" color="primary" fontWeight="medium" sx={{ mt: 0.5 }}>
                        {config.description}
                    </Typography>
                )}
            </DialogTitle>

            <DialogContent dividers>
                {error && (
                    <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError('')}>
                        {error}
                    </Alert>
                )}

                {/* Total et coût */}
                <Box sx={{ mb: 3 }}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
                        <Typography variant="body2" fontWeight="bold">
                            Total : {total} / {minTotal === maxTotal ? maxTotal : `${minTotal}–${maxTotal}`}
                        </Typography>
                        {hasPaidOptions && coutAdditionnel > 0 && (
                            <Chip label={`+${coutAdditionnel} pts`} size="small" color="primary" />
                        )}
                        {hasTransportOptions && (
                            <Chip label={`Places de transport : ${placesTransport}`} size="small" color="secondary" variant="outlined" />
                        )}
                    </Box>

                    {minTotal !== maxTotal && (
                        <Slider
                            value={total}
                            min={0}
                            max={maxTotal}
                            marks={[
                                { value: minTotal, label: `Min ${minTotal}` },
                                { value: maxTotal, label: `Max ${maxTotal}` }
                            ]}
                            disabled
                            sx={{ mt: 1 }}
                        />
                    )}
                </Box>

                {/* Options */}
                {config.options.map(option => (
                    <Box key={option.id} sx={{ mb: 2 }}>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5, flexWrap: 'wrap' }}>
                            <Typography variant="body2">
                                {option.name}
                                {option.max > 0 && ` (max ${option.max})`}
                            </Typography>
                            {(option.tags || []).map(tag => (
                                <Chip key={tag} label={tag} size="small" variant="outlined" color="default" />
                            ))}
                            {(option.cout || 0) > 0 && !option.cout_paliers && (
                                <Chip label={`${option.cout} pts/slot`} size="small" variant="outlined" />
                            )}
                            {option.cout_paliers && (
                                <Chip
                                    label={option.cout_paliers.map(p => `${p.cout}pts/${p.value ?? p.max}`).join(' ou ')}
                                    size="small"
                                    variant="outlined"
                                />
                            )}
                        </Box>
                        {(() => {
                            const curVal = composition[option.id] || 0;
                            const optMin = option.min || 0;
                            const bloquee = isOptionBloquee(option.id);
                            const optionMax = overrideTotal ? Math.max(option.max, overrideTotal) : option.max;
                            const optMax = bloquee ? 0 : Math.min(optionMax, maxTotal - total + curVal);
                            const range = optMax - optMin;
                            if (option.valeurs_possibles) {
                                const valeurs = [0, ...option.valeurs_possibles.filter(v => v > 0)];
                                return (
                                    <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mt: 1 }}>
                                        {valeurs.filter(v => v <= optMax || v === curVal).map(v => (
                                            <Chip
                                                key={v}
                                                label={v}
                                                onClick={() => !bloquee && handleChange(option.id, v)}
                                                color={curVal === v ? 'primary' : 'default'}
                                                variant={curVal === v ? 'filled' : 'outlined'}
                                                disabled={bloquee && v > 0}
                                                sx={{ fontSize: '1rem', height: 44, minWidth: 52 }}
                                            />
                                        ))}
                                    </Box>
                                );
                            }
                            if (range <= 6 && !option.force_slider) {
                                return (
                                    <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mt: 1 }}>
                                        {Array.from({ length: optMax - optMin + 1 }, (_, i) => optMin + i).map(v => (
                                            <Chip
                                                key={v}
                                                label={v}
                                                onClick={() => !bloquee && handleChange(option.id, v)}
                                                color={curVal === v ? 'primary' : 'default'}
                                                variant={curVal === v ? 'filled' : 'outlined'}
                                                disabled={bloquee && v > 0}
                                                sx={{ fontSize: '1rem', height: 44, minWidth: 52 }}
                                            />
                                        ))}
                                    </Box>
                                );
                            } else {
                                return (
                                    <Box sx={{ px: 1, mt: 2 }}>
                                        <Box sx={{ display: 'flex', justifyContent: 'center', mb: 1 }}>
                                            <Typography variant="h5" fontWeight="bold">{curVal}</Typography>
                                        </Box>
                                        <Slider
                                            value={curVal}
                                            min={optMin}
                                            max={optMax}
                                            step={1}
                                            marks
                                            onChange={(_, val) => handleChange(option.id, val)}
                                            valueLabelDisplay="auto"
                                        />
                                        <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                                            <Typography variant="caption" color="textSecondary">{optMin}</Typography>
                                            <Typography variant="caption" color="textSecondary">{optMax}</Typography>
                                        </Box>
                                    </Box>
                                );
                            }
                        })()}
                    </Box>
                ))}

                {!isValid && total > 0 && (
                    <Alert severity="warning" sx={{ mt: 2 }}>
                        {total < minTotal
                            ? `Il vous reste ${minTotal - total} slot(s) à sélectionner`
                            : `Vous avez sélectionné ${total - maxTotal} slot(s) en trop`
                        }
                    </Alert>
                )}

                {isValid && total > 0 && (
                    <Alert severity="success" sx={{ mt: 2 }}>
                        ✓ Configuration valide ({total} slot{total > 1 ? 's' : ''})
                        {hasPaidOptions && coutAdditionnel > 0 && ` — +${coutAdditionnel} pts`}
                    </Alert>
                )}
            </DialogContent>

            <DialogActions>
                <Button onClick={onClose}>Annuler</Button>
                <Button onClick={handleConfirm} variant="contained" disabled={!isValid}>
                    Valider
                </Button>
            </DialogActions>
        </Dialog>
    );
}

export default CompositionPersonnaliseeDialog;
