import React, { useState, useRef } from 'react';
import { DndContext, closestCenter, PointerSensor, TouchSensor, useSensor, useSensors } from '@dnd-kit/core';
import { SortableContext, verticalListSortingStrategy, useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import DragIndicatorIcon from '@mui/icons-material/DragIndicator';
import {
    Container,
    Box,
    Typography,
    Button,
    Paper,
    Select,
    MenuItem,
    Menu,
    FormControl,
    InputLabel,
    Chip,
    IconButton,
    Accordion,
    AccordionSummary,
    AccordionDetails,
    Divider,
    Alert,
    AlertTitle,
    Snackbar,
    TextField,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogContentText,
    DialogActions,
    ToggleButtonGroup,
    ToggleButton
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import DeleteIcon from '@mui/icons-material/Delete';
import ContentCopyIcon from '@mui/icons-material/ContentCopy';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import VisibilityIcon from '@mui/icons-material/Visibility';
import SaveIcon from '@mui/icons-material/Save';
import EditIcon from '@mui/icons-material/Edit';
import CheckIcon from '@mui/icons-material/Check';
import PrintIcon from '@mui/icons-material/Print';
import NoteAddIcon from '@mui/icons-material/NoteAdd';
import ArrowUpwardIcon from '@mui/icons-material/ArrowUpward';
import ArrowDownwardIcon from '@mui/icons-material/ArrowDownward';
import { useNavigate, useParams } from 'react-router-dom';
import { useArmyList } from '../../contexts/ArmyListContext';
import { useAuth } from '../../contexts/AuthContext';
import VarianteSelectorDialog from '../../components/VarianteSelectorDialog';
import CompositionPersonnaliseeDialog from '../../components/CompositionPersonnaliseeDialog';
import QuantiteSelectorDialog from '../../components/QuantiteSelectorDialog';
import ChoixAmeliorationDialog from '../../components/ChoixAmeliorationDialog';
import LimitePtsPopover from '../../components/LimitePtsPopover';

function ListBuilderPage({ codex }) {
    const {
        liste,
        validation,
        validator,
        ajouterFormation,
        modifierCompositionFormation,
        dupliquerFormation,
        supprimerFormation,
        selectionnerItem,
        ajouterAmelioration,
        supprimerAmelioration,
        calculerCoutTotal,
        sauvegarderListe,
        renommerListe,
        reordonnerFormations,
        reinitialiserListe,
        changerLimitePts
    } = useArmyList();

    const { user } = useAuth();
    const navigate = useNavigate();
    const { codexId } = useParams();

    // ✅ États pour sauvegarde et édition nom
    const [snackbar, setSnackbar] = useState({ open: false, message: '' });
    const [editingName, setEditingName] = useState(false);
    const [tempName, setTempName] = useState('');
    const [confirmNouvelleListeOpen, setConfirmNouvelleListeOpen] = useState(false);
    const [limitePtsAnchorEl, setLimitePtsAnchorEl] = useState(null);

    const handleSave = async () => {
        try {
            await sauvegarderListe(user);
            setSnackbar({ open: true, message: 'Liste sauvegardée !' });
        } catch (err) {
            setSnackbar({
                open: true,
                message: 'Liste sauvegardée localement, mais la synchronisation cloud a échoué. Elle ne sera pas visible sur vos autres appareils.'
            });
        }
    };

    const handleNouvelleListeConfirm = () => {
        reinitialiserListe();
        setConfirmNouvelleListeOpen(false);
    };

    const handleStartEditName = () => {
        setTempName(liste.nom);
        setEditingName(true);
    };

    const handleConfirmName = () => {
        if (tempName.trim()) {
            renommerListe(tempName.trim());
        }
        setEditingName(false);
    };

    const sensors = useSensors(
        useSensor(PointerSensor, { activationConstraint: { distance: 8 } }),
        useSensor(TouchSensor, { activationConstraint: { delay: 250, tolerance: 5 } })
    );

    const handleDragEnd = ({ active, over }) => {
        if (over && active.id !== over.id) {
            reordonnerFormations(active.id, over.id);
        }
    };

    // ✅ États pour les dialogs
    const [groupeExpand, setGroupeExpand] = useState(null);
    const [formationExpanded, setFormationExpanded] = useState({});

    const [varianteSelectorOpen, setVarianteSelectorOpen] = useState(false);
    const [currentFormationForVariante, setCurrentFormationForVariante] = useState(null);

    const [compositionDialogOpen, setCompositionDialogOpen] = useState(false);
    const [currentFormationForComposition, setCurrentFormationForComposition] = useState(null);
    const [pendingVarianteId, setPendingVarianteId] = useState(null);
    const [compositionOverrideTotal, setCompositionOverrideTotal] = useState(null);

    // ✅ Dialog composition synaptique (unités synaptiques libres)
    const [synaptiqueDialogOpen, setSynaptiqueDialogOpen] = useState(false);
    const [currentFormationForSynaptique, setCurrentFormationForSynaptique] = useState(null);

    // ✅ Dialog essaims (sélection obligatoire min/max)
    const [essaimDialogOpen, setEssaimDialogOpen] = useState(false);
    const [currentFormationForEssaims, setCurrentFormationForEssaims] = useState(null);

    // ✅ Accumulation entre les étapes de dialogue
    const [pendingUnites, setPendingUnites] = useState([]);
    const [pendingCout, setPendingCout] = useState(null);

    const [quantiteSelectorOpen, setQuantiteSelectorOpen] = useState(false);
    const [currentAmeliorationForQuantite, setCurrentAmeliorationForQuantite] = useState(null);
    const [currentFormationForQuantite, setCurrentFormationForQuantite] = useState(null);
    const [transportOverrideMax, setTransportOverrideMax] = useState(null);

    const [choixDialogOpen, setChoixDialogOpen] = useState(false);
    const [currentAmeliorationForChoix, setCurrentAmeliorationForChoix] = useState(null);
    const [currentFormationForChoix, setCurrentFormationForChoix] = useState(null);
    const [transportFilteredChoix, setTransportFilteredChoix] = useState(null);

    const [compoAmelioOpen, setCompoAmelioOpen] = useState(false);
    const [currentAmeliorationForCompo, setCurrentAmeliorationForCompo] = useState(null);
    const [currentFormationForCompoAmelio, setCurrentFormationForCompoAmelio] = useState(null);

    // ✅ États pour l'édition de composition d'une formation existante
    const [editVarianteSelectorOpen, setEditVarianteSelectorOpen] = useState(false);
    const [editCompositionOpen, setEditCompositionOpen] = useState(false);
    const [editFormationInstance, setEditFormationInstance] = useState(null);
    const [editFormationDef, setEditFormationDef] = useState(null);
    const [editPendingVarianteId, setEditPendingVarianteId] = useState(null);
    const [editCompositionOverrideTotal, setEditCompositionOverrideTotal] = useState(null);
    const [isEditingFormation, setIsEditingFormation] = useState(false);
    const editingFormationRef = useRef(null); // ref pour éviter les closures périmées
    const [editTargetId, setEditTargetId] = useState(null); // ID instance pour flux synaptique/essaims
    const [triFormations, setTriFormations] = useState('sans');
    const [triDirection, setTriDirection] = useState('asc');

    // ✅ Fonctions helpers
    const toggleFormation = (formationId) => {
        setFormationExpanded(prev => ({
            ...prev,
            [formationId]: !prev[formationId]
        }));
    };

    const trouverOptionDefDansCodex = (formationId, uniteId, optionId) => {
        for (const groupe of codex.groupes) {
            const formation = groupe.formations.find(f => f.id === formationId);
            if (formation) {
                const sources = [
                    ...(formation.unites || []),
                    ...(formation.variantes || []).flatMap(v => v.unites_override || [])
                ];
                const unite = sources.find(u => u.id === uniteId);
                if (unite?.options) {
                    const option = unite.options.find(o => o.id === optionId);
                    if (option) return option;
                }
            }
        }
        return null;
    };

    const trouverItemsDansCodex = (formationId, uniteId, optionId) => {
        const opt = trouverOptionDefDansCodex(formationId, uniteId, optionId);
        return opt ? (opt.items || []) : [];
    };

    const trouverFormationDef = (formationId) => {
        for (const groupe of codex.groupes) {
            const f = groupe.formations.find(fd => fd.id === formationId);
            if (f) return f;
        }
        return null;
    };

    const trouverGroupeFormation = (formationId) => {
        for (const groupe of codex.groupes) {
            if (groupe.formations.some(fd => fd.id === formationId)) return groupe;
        }
        return null;
    };

    const TYPE_ORDRE = { principale: 0, associee: 1, rare: 2 };

    const appliquerTri = (formations) => {
        if (triFormations === 'sans') return formations;
        const copy = [...formations];
        const dir = triDirection === 'asc' ? 1 : -1;
        if (triFormations === 'points') {
            copy.sort((a, b) => dir * (calculerCoutFormation(a) - calculerCoutFormation(b)));
        } else if (triFormations === 'taille') {
            const nbUnites = (f) => (f.unites || []).reduce((s, u) => s + (u.nombre || 1), 0);
            copy.sort((a, b) => dir * (nbUnites(a) - nbUnites(b)));
        } else if (triFormations === 'categorie') {
            copy.sort((a, b) => {
                const gA = trouverGroupeFormation(a.formationId);
                const gB = trouverGroupeFormation(b.formationId);
                const oA = TYPE_ORDRE[gA?.type] ?? 9;
                const oB = TYPE_ORDRE[gB?.type] ?? 9;
                if (oA !== oB) return dir * (oA - oB);
                return dir * (gA?.name || '').localeCompare(gB?.name || '');
            });
        }
        return copy;
    };

    const handleTriClick = (val) => {
        if (val === triFormations) {
            setTriDirection(d => d === 'asc' ? 'desc' : 'asc');
        } else {
            setTriFormations(val);
            setTriDirection('asc');
        }
    };

    const calculerTransportInfo = (formation, formationDef) => {
        const tailleMap = codex.codex.regles_speciales?.taille_transport;
        const capaciteMap = codex.codex.regles_speciales?.capacite_transport;
        if (!tailleMap || !capaciteMap) return null;

        // Utiliser les unités de l'instance (formation.unites) pour couvrir
        // les formations à composition_personnalisee dont formationDef.unites est vide
        let totalSlots = (formation.unites || []).reduce((sum, u) => {
            if (u.remplace) return sum;
            if (capaciteMap[u.uniteId]) return sum; // véhicule, pas passager
            return sum + (tailleMap[u.uniteId] || 0) * (u.nombre || 1);
        }, 0);

        formation.ameliorations.forEach(amelio => {
            const amelioDef = codex.ameliorations.find(a => a.id === amelio.ameliorationId);
            if (!amelioDef) return;
            // Les remplacements sont déjà comptés via formation.unites (est_remplacement)
            if (amelioDef.type_remplacement) return;
            const isTransport = (amelioDef.unites || []).some(u => capaciteMap[u.id]);
            if (isTransport) return;
            (amelioDef.unites || []).forEach(u => {
                totalSlots += (tailleMap[u.id] || 0) * (u.nombre || 1) * (amelio.quantite || 1);
            });
            // Perso ajouté via choix (ex: officier) — prend une place dans le transport
            if (amelioDef.choix && amelio.choixId) {
                const choixDef = amelioDef.choix.find(c => c.name === amelio.choixId);
                if (choixDef?.unitId && tailleMap[choixDef.unitId]) {
                    totalSlots += tailleMap[choixDef.unitId];
                }
            }
        });

        // Compter aussi les véhicules de transport déjà dans la formation de base
        let slotsCouverts = (formation.unites || []).reduce((sum, u) => {
            if (!capaciteMap[u.uniteId]) return sum;
            return sum + capaciteMap[u.uniteId] * (u.nombre || 1);
        }, 0);

        formation.ameliorations.forEach(amelio => {
            const amelioDef = codex.ameliorations.find(a => a.id === amelio.ameliorationId);
            if (!amelioDef) return;
            (amelioDef.unites || []).forEach(u => {
                if (!capaciteMap[u.id]) return;
                if (amelioDef.cout_par_unite) {
                    // nombre = unités par achat (ex: 2 pour chariot_flak acheté par paire)
                    slotsCouverts += capaciteMap[u.id] * (u.nombre || 1) * (amelio.quantite || 1);
                } else if (amelioDef.choix && amelio.choixId) {
                    const choixDef = amelioDef.choix.find(c => c.name === amelio.choixId);
                    if (choixDef?.nb_unites) slotsCouverts += capaciteMap[u.id] * choixDef.nb_unites;
                } else {
                    // Unités fixes (ex: devilfish_4, devilfish_6)
                    slotsCouverts += capaciteMap[u.id] * (u.nombre || 1);
                }
            });
            // Véhicules choisis via un slider composition_personnalisee d'amélioration
            (amelio.unitesComposition || []).forEach(u => {
                if (capaciteMap[u.uniteId]) {
                    slotsCouverts += capaciteMap[u.uniteId] * (u.nombre || 1);
                }
            });
            // Véhicules choisis via un choix avec unitId (type variable, unites vide)
            if (amelioDef.choix && amelio.choixId) {
                const choixDef = amelioDef.choix.find(c => c.name === amelio.choixId);
                if (choixDef?.unitId && choixDef?.nb_unites && capaciteMap[choixDef.unitId]) {
                    slotsCouverts += capaciteMap[choixDef.unitId] * choixDef.nb_unites;
                }
            }
        });

        return { totalSlots, slotsCouverts, slotsRestants: Math.max(0, totalSlots - slotsCouverts) };
    };

    const getTransportOverride = (amelio, formation) => {
        if (!amelio.IsNotOption) return null;
        const formationDef = trouverFormationDef(formation.formationId);
        if (!formationDef) return null;
        const info = calculerTransportInfo(formation, formationDef);
        if (!info) return null;
        const capaciteMap = codex.codex.regles_speciales?.capacite_transport;
        const transportUnitId = (amelio.unites || [])[0]?.id;
        const cap = capaciteMap?.[transportUnitId] || 0;
        if (!cap) return null;
        return { maxVehicules: Math.max(1, Math.ceil(info.slotsRestants / cap)), info };
    };

    const trouverAmeliorationsDansCodex = (formationId) => {
        for (const groupe of codex.groupes) {
            const formation = groupe.formations.find(f => f.id === formationId);
            if (formation && formation.ameliorations) {
                return formation.ameliorations.map(amelioId =>
                    codex.ameliorations.find(a => a.id === amelioId)
                ).filter(Boolean);
            }
        }
        return [];
    };

    const estAmelioTransport = (amelio) => {
        if (!amelio.IsNotOption) return false;
        const capaciteMap = codex.codex.regles_speciales?.capacite_transport;
        if (!capaciteMap) return false;
        const vehicleId = (amelio.unites || [])[0]?.id;
        return vehicleId !== undefined && capaciteMap[vehicleId] !== undefined;
    };

    const formationADesUnitesTransportables = (formationInstance) => {
        const tailleMap = codex.codex.regles_speciales?.taille_transport;
        if (!tailleMap) return false;
        return (formationInstance.unites || []).some(
            u => !u.est_remplacement && tailleMap[u.uniteId] !== undefined
        );
    };

    // Vérifie si les requires_unites d'une amélio sont satisfaites par la formation
    const amelioRequiresUnitesSatisfaites = (amelio, formationInstance) => {
        if (!amelio.requires_unites?.length) return true;
        // Unités de base de la formation
        const unitIds = new Set(
            (formationInstance.unites || []).map(u => u.uniteId)
        );
        // Unités ajoutées par des améliorations déjà présentes
        (formationInstance.ameliorations || []).forEach(a => {
            const def = codex.ameliorations.find(d => d.id === a.ameliorationId);
            (def?.unites || []).forEach(u => unitIds.add(u.id));
        });
        return amelio.requires_unites.some(id => unitIds.has(id));
    };

    const calculerCoutFormation = (formation) => {
        let cout = formation.cout;

        // Ajouter coût des items
        formation.unites?.forEach(unite => {
            unite.options?.forEach(option => {
                const items = trouverItemsDansCodex(formation.formationId, unite.uniteId, option.optionId);
                if (option.itemSelectionne) {
                    const item = items.find(i => i.id === option.itemSelectionne);
                    if (item) cout += item.cout;
                }
                (option.itemsMultiples || []).forEach(itemId => {
                    const item = items.find(i => i.id === itemId);
                    if (item) cout += item.cout;
                });
            });
        });

        // Ajouter coût des améliorations
        formation.ameliorations?.forEach(amelio => {
            const amelioDef = codex.ameliorations.find(a => a.id === amelio.ameliorationId);
            if (amelioDef) {
                if (amelio.coutOverride !== undefined && amelio.coutOverride !== null) {
                    cout += amelio.coutOverride;
                } else {
                    const choixDef = amelioDef.choix?.find(c => c.name === amelio.choixId);
                    const coutBase = choixDef?.cout ?? amelioDef.cout ?? 0;
                    if (amelioDef.cout_par_unite) {
                        const quantite = amelio.quantite || 1;
                        cout += coutBase * quantite;
                    } else {
                        cout += coutBase;
                    }
                }
            }
        });

        return cout;
    };

    // ✅ Helpers pour enchaîner les dialogs après variante/synaptique/composition
    const ouvrirSynaptique = (formation, varianteId = null) => {
        setPendingVarianteId(varianteId);
        setPendingUnites([]);
        setPendingCout(formation.cout);
        setCurrentFormationForSynaptique(formation);
        setSynaptiqueDialogOpen(true);
    };

    const ouvrirComposition = (formation, varianteId = null, overrideTotal = null) => {
        setPendingVarianteId(varianteId);
        setPendingUnites([]);
        setPendingCout(formation.cout);
        setCompositionOverrideTotal(overrideTotal);
        setCurrentFormationForComposition(formation);
        setCompositionDialogOpen(true);
    };

    const ouvrirEssaims = (formation, varianteId = null, unitesAccumulees = [], coutAccumule = null, instanceIdEdit = null) => {
        setPendingVarianteId(varianteId);
        setPendingUnites(unitesAccumulees);
        setPendingCout(coutAccumule ?? formation.cout);
        setCurrentFormationForEssaims(formation);
        if (instanceIdEdit !== null) setEditTargetId(instanceIdEdit);
        setEssaimDialogOpen(true);
    };

    // ✅ Handlers pour les dialogs
    const handleConfirmVariante = (varianteId) => {
        if (!currentFormationForVariante) return;
        const formation = currentFormationForVariante;
        setCurrentFormationForVariante(null);

        const variante = varianteId ? formation.variantes?.find(v => v.id === varianteId) : null;
        const coutVariante = variante?.cout ?? formation.cout;

        if (formation.composition_synaptique) {
            setPendingCout(coutVariante);
            ouvrirSynaptique(formation, varianteId);
        } else if (formation.composition_personnalisee) {
            const total = variante?.total_composition || formation.composition_personnalisee.total;
            ouvrirComposition(formation, varianteId, total);
        } else if (formation.composition_essaims) {
            ouvrirEssaims(formation, varianteId, [], coutVariante);
        } else {
            ajouterFormation(formation.id, varianteId);
        }
    };

    const handleConfirmSynaptique = (unites, coutAdd) => {
        if (!currentFormationForSynaptique) return;
        const formation = currentFormationForSynaptique;
        setCurrentFormationForSynaptique(null);

        if (editingFormationRef.current) {
            if (formation.composition_essaims) {
                ouvrirEssaims(formation, pendingVarianteId, unites, pendingCout, editingFormationRef.current.id);
            } else {
                modifierCompositionFormation(editingFormationRef.current.id, pendingVarianteId, unites, pendingCout);
                editingFormationRef.current = null;
                setEditTargetId(null);
                setEditFormationInstance(null);
                setEditFormationDef(null);
                setIsEditingFormation(false);
            }
        } else if (formation.composition_essaims) {
            ouvrirEssaims(formation, pendingVarianteId, unites, pendingCout);
        } else {
            ajouterFormation(formation.id, pendingVarianteId, unites, pendingCout);
        }
    };

    const handleConfirmComposition = (unites, coutAdd) => {
        if (!currentFormationForComposition) return;
        const formation = currentFormationForComposition;
        setCurrentFormationForComposition(null);
        setCompositionOverrideTotal(null);

        if (formation.composition_essaims) {
            ouvrirEssaims(formation, pendingVarianteId, unites, (pendingCout ?? formation.cout) + coutAdd);
        } else {
            ajouterFormation(formation.id, pendingVarianteId, unites);
            setPendingVarianteId(null);
        }
    };

    const handleConfirmEssaims = (essaimUnites, coutAdd) => {
        if (!currentFormationForEssaims) return;
        const formation = currentFormationForEssaims;
        setCurrentFormationForEssaims(null);

        const allUnites = [...pendingUnites, ...essaimUnites];
        const totalCout = (pendingCout ?? formation.cout) + coutAdd;

        const targetId = editTargetId;
        if (targetId) {
            modifierCompositionFormation(targetId, pendingVarianteId, allUnites, totalCout);
            editingFormationRef.current = null;
            setEditTargetId(null);
            setEditFormationInstance(null);
            setEditFormationDef(null);
            setIsEditingFormation(false);
        } else {
            ajouterFormation(formation.id, pendingVarianteId, allUnites, totalCout);
        }
        setPendingVarianteId(null);
        setPendingUnites([]);
        setPendingCout(null);
    };

    const handleConfirmQuantite = (quantite) => {
        if (currentFormationForQuantite && currentAmeliorationForQuantite) {
            ajouterAmelioration(
                currentFormationForQuantite.id,
                currentAmeliorationForQuantite.id,
                quantite
            );
            setCurrentAmeliorationForQuantite(null);
            setCurrentFormationForQuantite(null);
        }
    };

    const handleConfirmChoix = (choixId, choixName) => {
        if (currentFormationForChoix && currentAmeliorationForChoix) {
            ajouterAmelioration(
                currentFormationForChoix.id,
                currentAmeliorationForChoix.id,
                1,
                choixId,
                choixName
            );
            setCurrentAmeliorationForChoix(null);
            setCurrentFormationForChoix(null);
        }
    };

    const handleConfirmCompositionAmelio = (unites, coutAdditionnel = 0) => {
        if (currentFormationForCompoAmelio && currentAmeliorationForCompo) {
            ajouterAmelioration(
                currentFormationForCompoAmelio.id,
                currentAmeliorationForCompo.id,
                1,
                null,
                null,
                unites,
                (currentAmeliorationForCompo.cout || 0) + coutAdditionnel
            );
            setCurrentAmeliorationForCompo(null);
            setCurrentFormationForCompoAmelio(null);
        }
    };

    // ===== ÉDITION DE COMPOSITION =====
    const handleEditComposition = (formation) => {
        const formationDef = trouverFormationDef(formation.formationId);
        if (!formationDef) return;
        setEditFormationInstance(formation);
        setEditFormationDef(formationDef);
        if (formationDef.variantes?.length > 0) {
            setEditVarianteSelectorOpen(true);
        } else if (formationDef.composition_personnalisee) {
            setEditCompositionOpen(true);
        } else if (formationDef.composition_synaptique) {
            editingFormationRef.current = formation;
            setEditTargetId(formation.id);
            setIsEditingFormation(true);
            setPendingVarianteId(null);
            setPendingUnites([]);
            setPendingCout(formation.cout);
            setCurrentFormationForSynaptique(formationDef);
            setSynaptiqueDialogOpen(true);
        } else if (formationDef.composition_essaims) {
            editingFormationRef.current = formation;
            setEditTargetId(formation.id);
            setIsEditingFormation(true);
            setPendingVarianteId(null);
            setPendingUnites([]);
            setPendingCout(formationDef.cout);
            setCurrentFormationForEssaims(formationDef);
            setEssaimDialogOpen(true);
        }
    };

    const handleConfirmEditVariante = (varianteId) => {
        if (!editFormationInstance || !editFormationDef) return;
        setEditVarianteSelectorOpen(false);
        setEditPendingVarianteId(varianteId);
        if (editFormationDef.composition_personnalisee) {
            const variante = varianteId ? editFormationDef.variantes?.find(v => v.id === varianteId) : null;
            setEditCompositionOverrideTotal(variante?.total_composition || editFormationDef.composition_personnalisee.total);
            setEditCompositionOpen(true);
        } else {
            modifierCompositionFormation(editFormationInstance.id, varianteId);
            setEditFormationInstance(null);
            setEditFormationDef(null);
            setEditPendingVarianteId(null);
        }
    };

    const handleConfirmEditComposition = (unites) => {
        if (!editFormationInstance) return;
        modifierCompositionFormation(editFormationInstance.id, editPendingVarianteId, unites);
        setEditCompositionOpen(false);
        setEditFormationInstance(null);
        setEditFormationDef(null);
        setEditPendingVarianteId(null);
        setEditCompositionOverrideTotal(null);
    };

    const handleCloseEditVariante = () => {
        setEditVarianteSelectorOpen(false);
        setEditFormationInstance(null);
        setEditFormationDef(null);
    };

    const handleCloseEditComposition = () => {
        setEditCompositionOpen(false);
        setEditFormationInstance(null);
        setEditFormationDef(null);
        setEditPendingVarianteId(null);
        setEditCompositionOverrideTotal(null);
    };

    // ===== COPIE =====
    const [copyMenuAnchor, setCopyMenuAnchor] = useState(null);
    const [copyConfirm, setCopyConfirm] = useState('');
    const [copyMode, setCopyMode] = useState('normal'); // 'compact' | 'normal' | 'detaille'

    const coutBaseAmelioStr = (def, amelio) => {
        const choixDef = def.choix?.find(c => c.name === amelio.choixId);
        return choixDef?.cout ?? def.cout ?? 0;
    };

    const genererLigneAmelio = (amelio, sep) => {
        const def = codex.ameliorations.find(a => a.id === amelio.ameliorationId);
        if (!def) return '';
        const q = amelio.quantite || 1;
        const suffix = amelio.choixName ? ` : ${amelio.choixName}` : '';
        let coutAmelio;
        if (amelio.coutOverride !== undefined && amelio.coutOverride !== null) {
            coutAmelio = amelio.coutOverride;
        } else {
            const base = coutBaseAmelioStr(def, amelio);
            coutAmelio = def.cout_par_unite ? base * q : base;
        }
        return `  - ${q > 1 ? `${q}x ` : ''}${def.name}${suffix} (${coutAmelio} pts)`;
    };

    const genererContenu = (discord) => {
        const nl = discord ? '\r' : '\n';
        const maxCout = liste.formations.length > 0
            ? Math.max(...liste.formations.map(f => calculerCoutFormation(f))) : 0;
        const blms = liste.formations.filter(f => calculerCoutFormation(f) === maxCout);
        const blmLine = blms.length > 0
            ? (discord
                ? `***BLM : ${blms.map(b => b.nom).join(' / ')} — ${maxCout} pts***`
                : `BLM : ${blms.map(b => b.nom).join(' / ')} — ${maxCout} pts`)
            : '';

        const header = discord
            ? [`## ${codex.codex.name} — ${calculerCoutTotal()} pts`,
               `Formations : ***${liste.formations.filter(isFormationActive).length}***`,
               blmLine, '']
            : [`${codex.codex.name} — ${calculerCoutTotal()} pts`,
               `Formations : ${liste.formations.filter(isFormationActive).length}`,
               blmLine, ''];

        const lignes = liste.formations.map((formation, idx) => {
            const cout = calculerCoutFormation(formation);
            const varSuffix = formation.varianteName ? ` (${formation.varianteName})` : '';

            if (copyMode === 'compact') {
                return discord
                    ? `**${idx + 1}. ${formation.nom}${varSuffix}** — ${cout} pts`
                    : `${idx + 1}. ${formation.nom}${varSuffix} — ${cout} pts`;
            }

            const nomLigne = discord
                ? `**${idx + 1}. ${formation.nom}${varSuffix}** — ${cout} pts`
                : `${idx + 1}. ${formation.nom}${varSuffix} — ${cout} pts`;

            const amelioLignes = (formation.ameliorations || [])
                .map(a => genererLigneAmelio(a, nl))
                .filter(Boolean);

            if (copyMode === 'normal') {
                return [nomLigne, ...amelioLignes].join(nl);
            }

            // détaillé
            const uniteLignes = (formation.unites || [])
                .filter(u => !u.remplace)
                .map(u => `  • ${u.nombre > 1 ? `${u.nombre}× ` : ''}${u.nom}`);

            return [nomLigne, ...uniteLignes, ...amelioLignes].join(nl);
        });

        return [...header, ...lignes].filter(l => l !== null).join(nl);
    };

    const handleCopyDiscord = () => {
        navigator.clipboard.writeText(genererContenu(true))
            .then(() => { setCopyConfirm('discord'); setTimeout(() => setCopyConfirm(''), 2000); })
            .catch(console.error);
        setCopyMenuAnchor(null);
    };

    const handleCopyElo = () => {
        navigator.clipboard.writeText(genererContenu(false))
            .then(() => { setCopyConfirm('elo'); setTimeout(() => setCopyConfirm(''), 2000); })
            .catch(console.error);
        setCopyMenuAnchor(null);
    };

    const isFormationActive = (formation) => {
        for (const groupe of codex.groupes) {
            const def = groupe.formations.find(f => f.id === formation.formationId);
            if (def) return def.nbacti !== false;
        }
        return true;
    };

    const blmIds = (() => {
        if (liste.formations.length === 0) return new Set();
        const maxCout = Math.max(...liste.formations.map(f => calculerCoutFormation(f)));
        return new Set(liste.formations.filter(f => calculerCoutFormation(f) === maxCout).map(f => f.id));
    })();

    const hasCS = (formation) => formation.ameliorations?.some(amelio => {
        const amelioDef = codex.ameliorations.find(a => a.id === amelio.ameliorationId);
        if (!amelioDef) return false;
        if (amelioDef.commandant_supreme) return true;
        if (amelio.choixId && amelioDef.choix) {
            const choixDef = amelioDef.choix.find(c => c.id === amelio.choixId);
            return choixDef?.commandant_supreme === true;
        }
        return false;
    });

    const csFormation = liste.formations.find(hasCS);

    const regleCommissaireQuota = codex.codex?.regles_speciales?.commissaire_quota_soutien;
    const quotaCommissaireInfo = regleCommissaireQuota ? (() => {
        const pointsTotal = liste.formations.reduce((total, f) => total + calculerCoutFormation(f), 0);
        const quota = Math.ceil(pointsTotal / regleCommissaireQuota.points_par_tranche) || 0;
        const utilises = liste.formations.reduce((total, f) => {
            const hasCommissaire = f.ameliorations.some(a => {
                const aDef = codex.ameliorations.find(am => am.id === a.ameliorationId);
                return aDef?.regle_quota === 'commissaire_quota_soutien';
            });
            return total + (hasCommissaire ? 1 : 0);
        }, 0);
        return { quota, utilises };
    })() : null;

    return (
        <Container maxWidth="lg" sx={{ pt: 2, pb: 2 }}>
            {/* ========== HEADER ========== */}
            <Box sx={{ mb: 4 }}>
                <Typography variant="h4" gutterBottom>
                    {codex.codex.name}
                </Typography>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    {editingName ? (
                        <>
                            <TextField
                                value={tempName}
                                onChange={(e) => setTempName(e.target.value)}
                                size="small"
                                autoFocus
                                onKeyDown={(e) => {
                                    if (e.key === 'Enter') handleConfirmName();
                                    if (e.key === 'Escape') setEditingName(false);
                                }}
                            />
                            <IconButton size="small" onClick={handleConfirmName}>
                                <CheckIcon />
                            </IconButton>
                        </>
                    ) : (
                        <>
                            <Typography variant="h5" color="textSecondary">
                                {liste.nom}
                            </Typography>
                            <IconButton size="small" onClick={handleStartEditName}>
                                <EditIcon fontSize="small" />
                            </IconButton>
                        </>
                    )}
                </Box>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 1, flexWrap: 'wrap' }}>
                    <Chip
                        label={liste.limitePts != null
                            ? `${calculerCoutTotal()} / ${liste.limitePts} pts`
                            : `${calculerCoutTotal()} pts`
                        }
                        color={liste.limitePts != null && calculerCoutTotal() > liste.limitePts ? 'error' : 'primary'}
                        onClick={(e) => setLimitePtsAnchorEl(e.currentTarget)}
                        sx={{ cursor: 'pointer' }}
                    />
                    <LimitePtsPopover
                        anchorEl={limitePtsAnchorEl}
                        open={Boolean(limitePtsAnchorEl)}
                        onClose={() => setLimitePtsAnchorEl(null)}
                        limitePts={liste.limitePts}
                        onConfirm={(val) => changerLimitePts(val)}
                    />
                    <Chip label={`${liste.formations.filter(isFormationActive).length} formation${liste.formations.filter(isFormationActive).length > 1 ? 's' : ''}`} variant="outlined" />
                    {blmIds.size > 0 && (
                        <Chip
                            label={`BLM : ${liste.formations.filter(f => blmIds.has(f.id)).map(f => f.nom).join(' / ')}`}
                            size="small"
                            color="error"
                            variant="outlined"
                        />
                    )}
                    {csFormation && (
                        <Chip
                            label={`CS : ${csFormation.nom}`}
                            size="small"
                            color="warning"
                            variant="outlined"
                        />
                    )}
                    {quotaCommissaireInfo && (
                        <Chip
                            label={`COM : ${quotaCommissaireInfo.utilises}/${quotaCommissaireInfo.quota}`}
                            size="small"
                            color={quotaCommissaireInfo.utilises >= quotaCommissaireInfo.quota && quotaCommissaireInfo.quota > 0 ? 'default' : 'info'}
                            variant="outlined"
                            title="Commissaires disponibles dans les formations d'appui (1 gratuit par tranche de 1000 pts de Compagnies)"
                        />
                    )}
                    <IconButton
                        color="primary"
                        onClick={handleSave}
                        title="Sauvegarder la liste"
                        size="small"
                    >
                        <SaveIcon />
                    </IconButton>
                    <IconButton
                        color="primary"
                        onClick={() => setConfirmNouvelleListeOpen(true)}
                        title="Nouvelle liste"
                        size="small"
                    >
                        <NoteAddIcon />
                    </IconButton>
                    <IconButton
                        color="primary"
                        onClick={() => navigate(`/builder/${codexId}/preview`)}
                        title="Aperçu de la liste"
                        size="small"
                    >
                        <VisibilityIcon />
                    </IconButton>
                    <IconButton
                        color="primary"
                        onClick={() => navigate(`/builder/${codexId}/print`)}
                        title="Imprimer la liste"
                        size="small"
                    >
                        <PrintIcon />
                    </IconButton>
                    <IconButton
                        color={copyConfirm ? 'success' : 'primary'}
                        onClick={(e) => setCopyMenuAnchor(e.currentTarget)}
                        title="Copier la liste"
                        size="small"
                    >
                        <ContentCopyIcon />
                    </IconButton>
                    <Menu
                        anchorEl={copyMenuAnchor}
                        open={Boolean(copyMenuAnchor)}
                        onClose={() => setCopyMenuAnchor(null)}
                    >
                        <Box sx={{ px: 1.5, py: 0.5 }}>
                            <Typography variant="caption" color="textSecondary" display="block" sx={{ mb: 0.5 }}>
                                Niveau de détail
                            </Typography>
                            <ToggleButtonGroup
                                value={copyMode}
                                exclusive
                                onChange={(_, v) => { if (v) setCopyMode(v); }}
                                size="small"
                            >
                                <ToggleButton value="compact" sx={{ px: 1, py: 0.3, fontSize: '0.7rem' }}>Compact</ToggleButton>
                                <ToggleButton value="normal" sx={{ px: 1, py: 0.3, fontSize: '0.7rem' }}>Normal</ToggleButton>
                                <ToggleButton value="detaille" sx={{ px: 1, py: 0.3, fontSize: '0.7rem' }}>Détaillé</ToggleButton>
                            </ToggleButtonGroup>
                        </Box>
                        <Divider sx={{ my: 0.5 }} />
                        <MenuItem onClick={handleCopyDiscord}>
                            {copyConfirm === 'discord' ? '✓ Copié !' : 'Copier pour Discord'}
                        </MenuItem>
                        <MenuItem onClick={handleCopyElo}>
                            {copyConfirm === 'elo' ? '✓ Copié !' : 'Copier pour ELO'}
                        </MenuItem>
                    </Menu>
                </Box>
            </Box>

            {/* ========== LIMITE DE POINTS ========== */}
            {liste.limitePts != null && calculerCoutTotal() > liste.limitePts && (
                <Alert severity="warning" sx={{ mb: 2 }}>
                    <AlertTitle>Limite de points dépassée</AlertTitle>
                    {calculerCoutTotal()} pts — <strong>+{calculerCoutTotal() - liste.limitePts} pts</strong> au-dessus de la limite ({liste.limitePts} pts)
                </Alert>
            )}

            {/* ========== VALIDATION ALERTS ========== */}
            {validation?.errors?.length > 0 && (
                <Alert severity="error" sx={{ mb: 2 }}>
                    <AlertTitle>Erreurs de validation</AlertTitle>
                    {validation.errors.map((err, i) => (
                        <div key={i}>• {err.error}</div>
                    ))}
                </Alert>
            )}

            {validation?.warnings?.length > 0 && (
                <Alert severity="warning" sx={{ mb: 2 }}>
                    <AlertTitle>Avertissements</AlertTitle>
                    {validation.warnings.map((warn, i) => (
                        <div key={i}>• {warn.error}</div>
                    ))}
                </Alert>
            )}

            {validation?.infos?.length > 0 && (
                <Alert severity="info" sx={{ mb: 2 }}>
                    {validation.infos.map((info, i) => (
                        <div key={i}>{info.info}</div>
                    ))}
                </Alert>
            )}

            {/* ========== AJOUTER UNE FORMATION ========== */}
            <Paper sx={{ p: 2, mb: 3 }}>
                <Typography variant="h6" gutterBottom>
                    Ajouter une formation
                </Typography>

                {codex.groupes.map(groupe => (
                    <Accordion
                        key={groupe.id}
                        expanded={groupeExpand === groupe.id}
                        onChange={() => setGroupeExpand(groupeExpand === groupe.id ? null : groupe.id)}
                    >
                        <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                            <Typography>{groupe.name}</Typography>
                        </AccordionSummary>
                        <AccordionDetails>
                            <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
                                {groupe.formations.map(formation => {
                                    // ✅ Vérifier si la formation peut être ajoutée
                                    const canAdd = validator?.canAddFormation(liste, formation.id);
                                    const pointsRestants = liste.limitePts != null ? liste.limitePts - calculerCoutTotal() : Infinity;
                                    const isTooExpensive = formation.cout > pointsRestants;
                                    const isDisabled = (canAdd && !canAdd.valid) || isTooExpensive;

                                    return (
                                        <Button
                                            key={formation.id}
                                            variant="outlined"
                                            startIcon={<AddIcon />}
                                            disabled={isDisabled}
                                            onClick={() => {
                                                if (formation.variantes && formation.variantes.length > 0) {
                                                    setCurrentFormationForVariante(formation);
                                                    setVarianteSelectorOpen(true);
                                                } else if (formation.composition_synaptique) {
                                                    ouvrirSynaptique(formation);
                                                } else if (formation.composition_personnalisee) {
                                                    ouvrirComposition(formation);
                                                } else if (formation.composition_essaims) {
                                                    ouvrirEssaims(formation);
                                                } else {
                                                    ajouterFormation(formation.id);
                                                }
                                            }}
                                            size="small"
                                            sx={{
                                                ...(isDisabled && {
                                                    opacity: 0.5,
                                                    cursor: 'not-allowed'
                                                })
                                            }}
                                        >
                                            {formation.name} ({formation.cout} pts)
                                            {canAdd && !canAdd.valid && (
                                                <Chip label="Indisponible" size="small" color="error" sx={{ ml: 1 }} />
                                            )}
                                            {isTooExpensive && canAdd?.valid && (
                                                <Chip label={`+${formation.cout - pointsRestants} pts`} size="small" color="warning" sx={{ ml: 1 }} />
                                            )}
                                        </Button>
                                    );
                                })}
                            </Box>
                        </AccordionDetails>
                    </Accordion>
                ))}
            </Paper>

            {/* ========== LISTE DES FORMATIONS ========== */}
            <Box>
                <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 1, flexWrap: 'wrap', gap: 1 }}>
                    <Typography variant="h6">
                        Mes formations ({liste.formations.filter(isFormationActive).length})
                    </Typography>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <Typography variant="caption" color="textSecondary">Trier :</Typography>
                        <ToggleButtonGroup value={triFormations} exclusive size="small">
                            {[
                                { val: 'sans', label: 'Aucun' },
                                { val: 'categorie', label: 'Catégorie' },
                                { val: 'taille', label: 'Taille' },
                                { val: 'points', label: 'Points' },
                            ].map(({ val, label }) => (
                                <ToggleButton
                                    key={val}
                                    value={val}
                                    onClick={() => val === 'sans' ? (setTriFormations('sans'), setTriDirection('asc')) : handleTriClick(val)}
                                    sx={{ px: 1.5, py: 0.5, fontSize: '0.7rem', gap: 0.3 }}
                                >
                                    {label}
                                    {triFormations === val && val !== 'sans' && (
                                        triDirection === 'asc'
                                            ? <ArrowUpwardIcon sx={{ fontSize: '0.8rem' }} />
                                            : <ArrowDownwardIcon sx={{ fontSize: '0.8rem' }} />
                                    )}
                                </ToggleButton>
                            ))}
                        </ToggleButtonGroup>
                    </Box>
                </Box>

                {liste.formations.length === 0 && (
                    <Paper sx={{ p: 4, textAlign: 'center' }}>
                        <Typography color="textSecondary">
                            Aucune formation. Ajoutez-en une ci-dessus.
                        </Typography>
                    </Paper>
                )}

                <DndContext sensors={triFormations === 'sans' ? sensors : []} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
                    <SortableContext items={liste.formations.map(f => f.id)} strategy={verticalListSortingStrategy}>
                {appliquerTri(liste.formations).map(formation => (
                    <SortableFormationItem key={formation.id} id={formation.id} disabled={triFormations !== 'sans'}>
                    <Accordion
                        expanded={!!formationExpanded[formation.id]}
                        onChange={() => toggleFormation(formation.id)}
                        sx={{ mb: 1 }}
                    >
                        <AccordionSummary
                            expandIcon={<ExpandMoreIcon />}
                            sx={{
                                bgcolor: 'action.hover',
                                '&:hover': { bgcolor: 'action.selected' }
                            }}
                        >
                            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', width: '100%', pr: 2, gap: 1, flexWrap: 'wrap' }}>
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, flexWrap: 'wrap', flex: 1, minWidth: 0 }}>
                                    <DragHandle />
                                    <Typography variant="body1" fontWeight="bold" sx={{ lineHeight: 1.3 }}>
                                        {formation.nom}
                                    </Typography>
                                    {blmIds.has(formation.id) && (
                                        <Chip
                                            label="BLM"
                                            size="small"
                                            color="error"
                                            variant="outlined"
                                            title="Brigade de la Liste Maîtresse (formation la plus coûteuse)"
                                            sx={{ height: 20, fontSize: '0.7rem' }}
                                        />
                                    )}
                                    {hasCS(formation) && (
                                        <Chip
                                            label="CS"
                                            size="small"
                                            color="warning"
                                            variant="outlined"
                                            title="Commandant Suprême"
                                            sx={{ height: 20, fontSize: '0.7rem' }}
                                        />
                                    )}
                                    {formation.varianteName && (
                                        <Chip
                                            label={formation.varianteName}
                                            size="small"
                                            color="secondary"
                                            sx={{ height: 20, fontSize: '0.7rem' }}
                                        />
                                    )}
                                </Box>
                                <Chip
                                    label={`${calculerCoutFormation(formation)} pts`}
                                    color="primary"
                                    size="small"
                                    sx={{ flexShrink: 0, height: 22, fontSize: '0.75rem' }}
                                />
                            </Box>
                        </AccordionSummary>

                        <AccordionDetails>
                            <Box>
                                {/* ========== UNITÉS ========== */}
                                <Box sx={{ mb: 2 }}>
                                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, mb: 1 }}>
                                        <Typography variant="subtitle2" color="textSecondary">
                                            Composition :
                                        </Typography>
                                        {(() => {
                                            const formationDef = trouverFormationDef(formation.formationId);
                                            const canEdit = formationDef?.variantes?.length > 0 || formationDef?.composition_personnalisee || formationDef?.composition_synaptique || formationDef?.composition_essaims;
                                            if (!canEdit) return null;
                                            return (
                                                <IconButton size="small" onClick={() => handleEditComposition(formation)} title="Modifier la composition">
                                                    <EditIcon sx={{ fontSize: 14 }} />
                                                </IconButton>
                                            );
                                        })()}
                                    </Box>

                                    {formation.unites?.map(unite => (
                                        <Box
                                            key={unite.id}
                                            sx={{
                                                ml: 2,
                                                mb: 2,
                                                opacity: unite.remplace ? 0.5 : 1,
                                                textDecoration: unite.remplace ? 'line-through' : 'none'
                                            }}
                                        >
                                            <Typography
                                                variant="body1"
                                                gutterBottom
                                                fontWeight="medium"
                                                color={unite.est_remplacement ? 'primary.main' : 'inherit'}
                                            >
                                                {unite.instanceIndex
                                                    ? `${unite.nom} (${unite.instanceIndex}/${unite.instanceTotal})`
                                                    : `${unite.nombre}x ${unite.nom}`}
                                                {unite.est_remplacement && (
                                                    <Chip label="Remplacement" size="small" color="primary" sx={{ ml: 1 }} />
                                                )}
                                            </Typography>

                                            {/* Options */}
                                            {unite.options?.map(option => {
                                                const items = trouverItemsDansCodex(formation.formationId, unite.uniteId, option.optionId);
                                                const optionDef = trouverOptionDefDansCodex(formation.formationId, unite.uniteId, option.optionId);
                                                const isMultiple = optionDef?.multiple;

                                                if (isMultiple) {
                                                    const selected = option.itemsMultiples || [];
                                                    return (
                                                        <Box key={option.optionId} sx={{ mt: 1 }}>
                                                            <Typography variant="caption" color="textSecondary">
                                                                {option.nom} :
                                                            </Typography>
                                                            <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5, mt: 0.5 }}>
                                                                {items.map(item => {
                                                                    const isSelected = selected.includes(item.id);
                                                                    return (
                                                                        <Chip
                                                                            key={item.id}
                                                                            label={`${item.name}${item.cout > 0 ? ` (${item.cout} pts)` : ''}`}
                                                                            onClick={() => selectionnerItem(formation.id, unite.id, option.optionId, item.id)}
                                                                            color={isSelected ? 'primary' : 'default'}
                                                                            variant={isSelected ? 'filled' : 'outlined'}
                                                                            size="small"
                                                                            sx={{ cursor: 'pointer' }}
                                                                        />
                                                                    );
                                                                })}
                                                            </Box>
                                                        </Box>
                                                    );
                                                }

                                                return (
                                                    <FormControl
                                                        fullWidth
                                                        key={option.optionId}
                                                        size="small"
                                                        sx={{ mt: 1 }}
                                                    >
                                                        <InputLabel>
                                                            {option.nom}
                                                            {optionDef?.requis && ' *'}
                                                        </InputLabel>
                                                        <Select
                                                            value={option.itemSelectionne || ''}
                                                            label={option.nom + (optionDef?.requis ? ' *' : '')}
                                                            onChange={(e) => selectionnerItem(formation.id, unite.id, option.optionId, e.target.value)}
                                                        >
                                                            <MenuItem value="">
                                                                <em>-- Aucun --</em>
                                                            </MenuItem>
                                                            {items.map(item => (
                                                                <MenuItem key={item.id} value={item.id}>
                                                                    {item.name} {item.cout > 0 && `(${item.cout} pts)`}
                                                                </MenuItem>
                                                            ))}
                                                        </Select>
                                                    </FormControl>
                                                );
                                            })}
                                        </Box>
                                    ))}

                                    {formation.ameliorations?.map(amelio => {
                                        const amelioDef = codex.ameliorations.find(a => a.id === amelio.ameliorationId);
                                        const unitesAAfficher = amelio.choixUnites ?? (amelioDef?.affiche_dans_composition ? amelioDef.unites : null);
                                        if (!unitesAAfficher?.length) return null;
                                        return unitesAAfficher.map(u => (
                                            <Box key={`${amelio.id}_${u.id}`} sx={{ ml: 2, mb: 2 }}>
                                                <Typography variant="body1" gutterBottom fontWeight="medium">
                                                    {`${u.nombre * (amelio.quantite || 1)}x ${u.name}`}
                                                </Typography>
                                            </Box>
                                        ));
                                    })}
                                </Box>

                                <Divider sx={{ my: 2 }} />

                                {/* ========== AMÉLIORATIONS ========== */}
                                <Box>
                                    <Typography variant="subtitle2" gutterBottom color="textSecondary">
                                        Améliorations :
                                    </Typography>

                                    {formation.ameliorations?.length === 0 && (
                                        <Typography variant="body2" color="textSecondary" sx={{ ml: 2 }}>
                                            Aucune
                                        </Typography>
                                    )}

                                    <Box sx={{ ml: 2, mb: 2, display: 'flex', flexWrap: 'wrap' }}>
                                        {formation.ameliorations?.map(amelio => {
                                            const amelioDef = codex.ameliorations.find(a => a.id === amelio.ameliorationId);
                                            const quantite = amelio.quantite || 1;
                                            const choixDef = amelioDef?.choix?.find(c => c.name === amelio.choixId);
                                            const coutBase = choixDef?.cout ?? amelioDef?.cout ?? 0;
                                            const coutTotal = (amelio.coutOverride !== undefined && amelio.coutOverride !== null)
                                                ? amelio.coutOverride
                                                : (amelioDef?.cout_par_unite ? coutBase * quantite : coutBase);
                                            const choixSuffix = amelio.choixName ? ` : ${amelio.choixName}` : '';
                                            const compoSuffix = amelio.unitesComposition?.length
                                                ? ` : ${amelio.unitesComposition.map(u => `${u.nombre}x ${u.nom}`).join(', ')}`
                                                : '';

                                            return (
                                                <Chip
                                                    key={amelio.id}
                                                    label={`${quantite > 1 ? `${quantite}x ` : ''}${amelioDef?.name}${choixSuffix}${compoSuffix} (${coutTotal} pts)`}
                                                    onDelete={() => supprimerAmelioration(formation.id, amelio.id)}
                                                    sx={{ m: 0.5 }}
                                                    size="small"
                                                />
                                            );
                                        })}
                                    </Box>

                                    {/* ========== TRANSPORT SLOTS ========== */}
                                    {(() => {
                                        const capaciteMap = codex.codex.regles_speciales?.capacite_transport;
                                        if (!capaciteMap) return null;
                                        const hasTransportAmelio = formation.ameliorations?.some(amelio => {
                                            const amelioDef = codex.ameliorations.find(a => a.id === amelio.ameliorationId);
                                            if ((amelioDef?.unites || []).some(u => capaciteMap[u.id])) return true;
                                            // Slider composition_personnalisee avec véhicules de transport
                                            if ((amelio.unitesComposition || []).some(u => capaciteMap[u.uniteId])) return true;
                                            if ((amelioDef?.composition_personnalisee?.options || []).some(o => capaciteMap[o.unitId])) return true;
                                            // Choix avec unitId (type de véhicule variable selon le choix)
                                            if ((amelioDef?.choix || []).some(c => c.unitId && capaciteMap[c.unitId])) return true;
                                            return false;
                                        });
                                        if (!hasTransportAmelio) return null;
                                        const formationDef = trouverFormationDef(formation.formationId);
                                        if (!formationDef) return null;
                                        const info = calculerTransportInfo(formation, formationDef);
                                        if (!info) return null;
                                        const isComplete = info.slotsRestants === 0;
                                        return (
                                            <Box sx={{ ml: 2, mb: 1, display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
                                                <Typography variant="caption" color="textSecondary">
                                                    Transport :
                                                </Typography>
                                                <Chip
                                                    label={`${info.slotsCouverts} / ${info.totalSlots} places`}
                                                    size="small"
                                                    color={isComplete ? 'success' : 'warning'}
                                                    variant="outlined"
                                                />
                                                {!isComplete && (
                                                    <Typography variant="caption" color="warning.main">
                                                        {info.slotsRestants} place{info.slotsRestants > 1 ? 's' : ''} non couverte{info.slotsRestants > 1 ? 's' : ''}
                                                    </Typography>
                                                )}
                                            </Box>
                                        );
                                    })()}

                                    <Box sx={{ ml: 2, display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                                        {trouverAmeliorationsDansCodex(formation.formationId)
                                            .filter(amelio => !estAmelioTransport(amelio) || formationADesUnitesTransportables(formation))
                                            .filter(amelio => amelioRequiresUnitesSatisfaites(amelio, formation))
                                            .map(amelio => {
                                            const needsQuantity = (amelio.min !== undefined && amelio.max !== undefined) ||
                                                (amelio.type_remplacement && !amelio.type_remplacement.remplace_tout && !amelio.type_remplacement.quantite_fixe);
                                            const quotaReached = amelio.regle_quota && quotaCommissaireInfo &&
                                                quotaCommissaireInfo.utilises >= quotaCommissaireInfo.quota;

                                            return (
                                                <Button
                                                    key={amelio.id}
                                                    size="small"
                                                    variant="outlined"
                                                    disabled={!!quotaReached}
                                                    title={quotaReached ? `Quota Commissaires atteint (${quotaCommissaireInfo.utilises}/${quotaCommissaireInfo.quota})` : undefined}
                                                    onClick={() => {
                                                        if (amelio.choix) {
                                                            const override = getTransportOverride(amelio, formation);
                                                            if (override) {
                                                                setTransportFilteredChoix(amelio.choix.filter(c => (c.nb_unites || 1) <= override.maxVehicules));
                                                            } else {
                                                                setTransportFilteredChoix(null);
                                                            }
                                                            setCurrentAmeliorationForChoix(amelio);
                                                            setCurrentFormationForChoix(formation);
                                                            setChoixDialogOpen(true);
                                                        } else if (amelio.composition_personnalisee) {
                                                            setCurrentAmeliorationForCompo(amelio);
                                                            setCurrentFormationForCompoAmelio(formation);
                                                            setCompoAmelioOpen(true);
                                                        } else if (needsQuantity) {
                                                            const override = getTransportOverride(amelio, formation);
                                                            setTransportOverrideMax(override ? override.maxVehicules : null);
                                                            setCurrentAmeliorationForQuantite(amelio);
                                                            setCurrentFormationForQuantite(formation);
                                                            setQuantiteSelectorOpen(true);
                                                        } else {
                                                            ajouterAmelioration(formation.id, amelio.id);
                                                        }
                                                    }}
                                                >
                                                    + {amelio.name} ({(() => {
                                                        if (amelio.choix?.length > 0) {
                                                            const costs = amelio.choix.map(c => c.cout).filter(c => c > 0);
                                                            if (costs.length === 0) return `${amelio.cout} pts`;
                                                            const min = Math.min(...costs);
                                                            const max = Math.max(...costs);
                                                            return min === max ? `${min} pts` : `${min} / ${max} pts`;
                                                        }
                                                        return `${amelio.cout} pts`;
                                                    })()})
                                                </Button>
                                            );
                                        })}
                                    </Box>
                                </Box>

                                <Divider sx={{ my: 2 }} />

                                {/* ========== ACTIONS ========== */}
                                <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 1 }}>
                                    <Button
                                        startIcon={<ContentCopyIcon />}
                                        onClick={() => dupliquerFormation(formation.id)}
                                    >
                                        Dupliquer
                                    </Button>
                                    <Button
                                        color="error"
                                        startIcon={<DeleteIcon />}
                                        onClick={() => supprimerFormation(formation.id)}
                                    >
                                        Supprimer
                                    </Button>
                                </Box>
                            </Box>
                        </AccordionDetails>
                    </Accordion>
                    </SortableFormationItem>
                ))}
                    </SortableContext>
                </DndContext>
            </Box>

            {/* ========== DIALOGS ========== */}

            {/* Dialog sélection de variante */}
            <VarianteSelectorDialog
                open={varianteSelectorOpen}
                onClose={() => {
                    setVarianteSelectorOpen(false);
                    setCurrentFormationForVariante(null);
                }}
                formation={currentFormationForVariante}
                onConfirm={handleConfirmVariante}
            />

            {/* Dialog composition personnalisée */}
            <CompositionPersonnaliseeDialog
                capaciteTransportMap={codex.codex.regles_speciales?.capacite_transport}
                open={compositionDialogOpen}
                onClose={() => {
                    setCompositionDialogOpen(false);
                    setCurrentFormationForComposition(null);
                    setPendingVarianteId(null);
                    setCompositionOverrideTotal(null);
                }}
                formationDef={currentFormationForComposition}
                onConfirm={handleConfirmComposition}
                overrideTotal={compositionOverrideTotal}
            />

            {/* Dialog composition synaptique (unités synaptiques libres) */}
            <CompositionPersonnaliseeDialog
                open={synaptiqueDialogOpen}
                onClose={() => {
                    setSynaptiqueDialogOpen(false);
                    setCurrentFormationForSynaptique(null);
                    setPendingVarianteId(null);
                    editingFormationRef.current = null; setEditTargetId(null); setIsEditingFormation(false); setEditFormationInstance(null); setEditFormationDef(null);
                }}
                formationDef={currentFormationForSynaptique}
                configOverride={currentFormationForSynaptique?.composition_synaptique}
                dialogTitle={currentFormationForSynaptique?.name}
                onConfirm={handleConfirmSynaptique}
            />

            {/* Dialog sélection d'essaims (min/max obligatoire) */}
            <CompositionPersonnaliseeDialog
                open={essaimDialogOpen}
                onClose={() => {
                    setEssaimDialogOpen(false);
                    setCurrentFormationForEssaims(null);
                    setPendingVarianteId(null);
                    setPendingUnites([]);
                    setPendingCout(null);
                    editingFormationRef.current = null; setEditTargetId(null); setIsEditingFormation(false); setEditFormationInstance(null); setEditFormationDef(null);
                }}
                formationDef={currentFormationForEssaims}
                configOverride={currentFormationForEssaims?.composition_essaims}
                dialogTitle={currentFormationForEssaims?.name}
                onConfirm={handleConfirmEssaims}
            />

            {/* Dialog composition amélioration (ex: Blindés T'au) */}
            <CompositionPersonnaliseeDialog
                capaciteTransportMap={codex.codex.regles_speciales?.capacite_transport}
                open={compoAmelioOpen}
                onClose={() => {
                    setCompoAmelioOpen(false);
                    setCurrentAmeliorationForCompo(null);
                    setCurrentFormationForCompoAmelio(null);
                }}
                configOverride={currentAmeliorationForCompo?.composition_personnalisee}
                dialogTitle={currentAmeliorationForCompo?.name}
                onConfirm={handleConfirmCompositionAmelio}
            />

            {/* Dialog choix d'amélioration */}
            <ChoixAmeliorationDialog
                open={choixDialogOpen}
                onClose={() => {
                    setChoixDialogOpen(false);
                    setCurrentAmeliorationForChoix(null);
                    setCurrentFormationForChoix(null);
                    setTransportFilteredChoix(null);
                }}
                amelioration={currentAmeliorationForChoix}
                onConfirm={handleConfirmChoix}
                filteredChoix={transportFilteredChoix}
                faction={codex.codex.faction}
            />

            {/* Dialog sélection de quantité */}
            <QuantiteSelectorDialog
                open={quantiteSelectorOpen}
                onClose={() => {
                    setQuantiteSelectorOpen(false);
                    setCurrentAmeliorationForQuantite(null);
                    setCurrentFormationForQuantite(null);
                    setTransportOverrideMax(null);
                }}
                amelioration={currentAmeliorationForQuantite}
                formation={currentFormationForQuantite}
                onConfirm={handleConfirmQuantite}
                overrideMax={transportOverrideMax}
            />

            {/* Dialog édition variante d'une formation existante */}
            <VarianteSelectorDialog
                open={editVarianteSelectorOpen}
                onClose={handleCloseEditVariante}
                formation={editFormationDef}
                onConfirm={handleConfirmEditVariante}
                initialVarianteId={editFormationInstance?.varianteId ?? null}
                confirmLabel="Confirmer"
            />

            {/* Dialog édition composition personnalisée d'une formation existante */}
            <CompositionPersonnaliseeDialog
                capaciteTransportMap={codex.codex.regles_speciales?.capacite_transport}
                open={editCompositionOpen}
                onClose={handleCloseEditComposition}
                formationDef={editFormationDef}
                onConfirm={handleConfirmEditComposition}
                overrideTotal={editCompositionOverrideTotal}
            />

            <Snackbar
                open={snackbar.open}
                autoHideDuration={3000}
                onClose={() => setSnackbar({ open: false, message: '' })}
                message={snackbar.message}
            />

            <Dialog open={confirmNouvelleListeOpen} onClose={() => setConfirmNouvelleListeOpen(false)}>
                <DialogTitle>Nouvelle liste</DialogTitle>
                <DialogContent>
                    <DialogContentText>
                        Créer une nouvelle liste ? La liste en cours sera perdue si elle n'a pas été sauvegardée.
                    </DialogContentText>
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setConfirmNouvelleListeOpen(false)}>Annuler</Button>
                    <Button onClick={handleNouvelleListeConfirm} color="primary" variant="contained">
                        Nouvelle liste
                    </Button>
                </DialogActions>
            </Dialog>
        </Container>
    );
}

const DragListenersContext = React.createContext(null);

function SortableFormationItem({ id, children, disabled }) {
    const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id, disabled });
    return (
        <DragListenersContext.Provider value={disabled ? null : listeners}>
            <div
                ref={setNodeRef}
                style={{
                    transform: CSS.Transform.toString(transform),
                    transition,
                    opacity: isDragging ? 0.5 : 1,
                    position: 'relative',
                    zIndex: isDragging ? 1 : 'auto'
                }}
                {...attributes}
            >
                {children}
            </div>
        </DragListenersContext.Provider>
    );
}

function DragHandle() {
    const listeners = React.useContext(DragListenersContext);
    if (!listeners) return null;
    return (
        <IconButton
            size="small"
            sx={{ cursor: 'grab', color: 'text.disabled', mr: 0.5, touchAction: 'none' }}
            {...listeners}
            onClick={e => e.stopPropagation()}
        >
            <DragIndicatorIcon fontSize="small" />
        </IconButton>
    );
}

export default ListBuilderPage;