import { db } from '../firebase';
import { collection, doc, getDocs, getDoc, setDoc, deleteDoc } from 'firebase/firestore';

const LOCAL_STORAGE_KEY = 'epic_lists';

// ========== LOCAL STORAGE ==========

function getLocalLists() {
    try {
        const data = localStorage.getItem(LOCAL_STORAGE_KEY);
        return data ? JSON.parse(data) : [];
    } catch {
        return [];
    }
}

function saveLocalList(list) {
    const lists = getLocalLists();
    const index = lists.findIndex(l => l.id === list.id);
    if (index >= 0) {
        lists[index] = list;
    } else {
        lists.push(list);
    }
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(lists));
}

function deleteLocalList(listId) {
    const lists = getLocalLists().filter(l => l.id !== listId);
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(lists));
}

// ========== FIRESTORE — LISTES PRIVÉES ==========

async function getFirestoreLists(uid) {
    try {
        const ref = collection(db, 'users', uid, 'lists');
        const snapshot = await getDocs(ref);
        return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
    } catch (err) {
        console.error('Erreur Firestore (lecture):', err);
        return [];
    }
}

async function saveFirestoreList(uid, list) {
    try {
        const ref = doc(db, 'users', uid, 'lists', list.id);
        await setDoc(ref, list);
    } catch (err) {
        console.error('Erreur Firestore (écriture):', err);
        throw err; // remonte l'erreur : un échec silencieux désynchronise les appareils
    }
}

async function deleteFirestoreList(uid, listId) {
    try {
        const ref = doc(db, 'users', uid, 'lists', listId);
        await deleteDoc(ref);
    } catch (err) {
        console.error('Erreur Firestore (suppression):', err);
    }
}

// ========== FIRESTORE — LISTES PUBLIQUES ==========

async function getFirestorePublicLists() {
    try {
        const ref = collection(db, 'public_lists');
        const snapshot = await getDocs(ref);
        return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
    } catch (err) {
        console.error('Erreur Firestore (listes publiques):', err);
        return [];
    }
}

async function saveFirestorePublicList(list, ownerDisplayName) {
    try {
        const ref = doc(db, 'public_lists', list.id);
        await setDoc(ref, { ...list, ownerDisplayName: ownerDisplayName || 'Anonyme' });
        console.log('[public_lists] Écriture OK pour', list.id);
    } catch (err) {
        console.error('[public_lists] Erreur écriture (vérifier les règles Firestore):', err.code, err.message);
        throw err; // remonte l'erreur pour que toggleListePublique puisse la signaler
    }
}

async function deleteFirestorePublicList(listId) {
    try {
        const ref = doc(db, 'public_lists', listId);
        await deleteDoc(ref);
    } catch (err) {
        console.error('Erreur Firestore (suppression publique):', err);
    }
}

// ========== API EXPORTÉE ==========

export async function saveListe(list, user) {
    saveLocalList(list);
    if (user) {
        await saveFirestoreList(user.uid, list);
        // Mettre à jour la version publique si la liste est publique
        if (list.publique) {
            await saveFirestorePublicList(list, user.displayName || user.email);
        }
    }
}

export async function loadAllListes(user) {
    const localLists = getLocalLists();

    if (!user) return localLists;

    const firestoreLists = await getFirestoreLists(user.uid);

    // Merge : plus récent gagne par id
    const merged = new Map();
    for (const list of localLists) {
        merged.set(list.id, list);
    }
    for (const list of firestoreLists) {
        const existing = merged.get(list.id);
        if (!existing || new Date(list.dateModification) > new Date(existing.dateModification)) {
            merged.set(list.id, list);
        }
    }

    return Array.from(merged.values());
}

export async function deleteListe(listId, user) {
    deleteLocalList(listId);
    if (user) {
        await deleteFirestoreList(user.uid, listId);
        await deleteFirestorePublicList(listId);
    }
}

export async function loadPublicListes() {
    return getFirestorePublicLists();
}

export async function loadPublicListeById(listId) {
    try {
        const ref = doc(db, 'public_lists', listId);
        const snapshot = await getDoc(ref);
        if (snapshot.exists()) return { id: snapshot.id, ...snapshot.data() };
        return null;
    } catch (err) {
        console.error('Erreur Firestore (chargement liste publique):', err);
        return null;
    }
}

export async function toggleListePublique(list, user, isPublic) {
    const updatedList = { ...list, publique: isPublic, ownerUid: user.uid };
    saveLocalList(updatedList);
    await saveFirestoreList(user.uid, updatedList);
    if (isPublic) {
        try {
            await saveFirestorePublicList(updatedList, user.displayName || user.email);
        } catch (err) {
            // Écriture publique refusée — on remet publique: false pour rester cohérent
            const revert = { ...updatedList, publique: false };
            saveLocalList(revert);
            await saveFirestoreList(user.uid, revert);
            throw new Error('Permission refusée pour rendre la liste publique. Vérifiez les règles Firestore.');
        }
    } else {
        await deleteFirestorePublicList(list.id);
    }
    return updatedList;
}
