import { FormationValidator } from './validators/FormationValidator';
import { AmeliorationValidator } from './validators/AmeliorationValidator';
import { RareValidator } from './validators/RareValidator';
import { DependencyValidator } from './validators/DependencyValidator';
/**
 * Moteur de validation central
 */
export class ValidationEngine {

    constructor(codex) {
        this.codex = codex;
    }

    /**
     * Valide toute la liste
     */
    validateListe(liste) {
        const errors = [];
        const warnings = [];
        const infos = [];

        const pointsTotal = this.calculerPointsTotal(liste);

        // 1. Validation quota rare
        const rareResult = RareValidator.validateQuotaRare(liste, this.codex, pointsTotal, liste.limitePts ?? null);
        if (!rareResult.valid) {
            errors.push(rareResult);
        } else if (rareResult.info) {
            infos.push(rareResult);
        }

        // 1b. Validation assignation globale des slots (backtracking)
        const slotResult = DependencyValidator.validerAssignationGlobale(liste, this.codex);
        if (!slotResult.valid) {
            errors.push(slotResult);
        }

        // 2. Validation min formations par groupe
        this.codex.groupes.forEach(groupe => {
            const result = FormationValidator.validateMinFormations(liste, this.codex, groupe);
            if (!result.valid) {
                if (result.blocking) {
                    errors.push(result);
                } else {
                    warnings.push(result);
                }
            }
        });

        // 2b. Validation du nombre d'unités max par formation (selon améliorations)
        liste.formations.forEach(formation => {
            formation.ameliorations.forEach(amelio => {
                const amelioDef = this.codex.ameliorations.find(a => a.id === amelio.ameliorationId);
                if (!amelioDef?.max_unites_formation) return;

                const totalUnites = formation.unites.reduce((total, unite) => {
                    if (unite.remplace) return total;
                    return total + (unite.nombre || 1);
                }, 0);

                if (totalUnites > amelioDef.max_unites_formation) {
                    errors.push({
                        valid: false,
                        error: `${formation.nom || formation.formationId} : "${amelioDef.name}" nécessite une formation de ${amelioDef.max_unites_formation} unités maximum (${totalUnites} actuellement)`,
                        type: 'MAX_UNITES_FORMATION',
                        blocking: true
                    });
                }
            });
        });

        // 3. Validation améliorations obligatoires
        liste.formations.forEach(formation => {
            const formationDef = this.findFormation(formation.formationId);
            if (!formationDef) return;

            (formationDef.ameliorations_obligatoires || []).forEach(ameliorationId => {
                const hasIt = formation.ameliorations.some(a => a.ameliorationId === ameliorationId);
                if (!hasIt) {
                    const amelioDef = this.codex.ameliorations.find(a => a.id === ameliorationId);
                    errors.push({
                        valid: false,
                        error: `"${amelioDef?.name || ameliorationId}" est obligatoire dans ${formationDef.name}`,
                        type: 'AMELIORATION_OBLIGATOIRE',
                        blocking: true
                    });
                }
            });
        });

        return {
            valid: errors.length === 0,
            errors,
            warnings,
            infos
        };
    }

    /**
     * Vérifie si on peut ajouter une formation
     */
    canAddFormation(liste, formationId) {
        const formationDef = this.findFormation(formationId);
        if (!formationDef) return { valid: false, error: 'Formation introuvable' };

        // 1. Vérifier limite formation
        const limiteResult = FormationValidator.validateFormationLimite(liste, formationDef);
        if (!limiteResult.valid) return limiteResult;

        // ✅ 2. Vérifier LimitationTag (simulation + backtracking)
        const tagResult = DependencyValidator.validateLimitationTag(liste, this.codex, formationDef);
        if (!tagResult.valid) return tagResult;

        // ✅ 3. Vérifier max_par_tag
        const maxTagResult = DependencyValidator.validateMaxParTag(liste, this.codex, formationDef);
        if (!maxTagResult.valid) return maxTagResult;

        // ✅ 4. Vérifier quota rare
        if (formationDef.rare) {
            const pointsTotal = this.calculerPointsTotal(liste);
            const ratio = this.codex.codex.regles_speciales?.max_formations_rares_ratio || (1/3);
            const label = this.codex.codex.regles_speciales?.label_rares || 'Formations rares';
            const base = liste.limitePts ?? pointsTotal;
            const tranche = Math.ceil(base / 1000) * 1000;
            const maxPointsRares = Math.round(tranche * ratio);
            const pointsRaresActuels = RareValidator.calculerPointsRares(liste, this.codex);
            const coutRare = formationDef.cout_rare_base ?? formationDef.cout;
            if (pointsRaresActuels + coutRare > maxPointsRares) {
                return {
                    valid: false,
                    error: `${label} : quota dépassé (${pointsRaresActuels + coutRare} pts > max ${maxPointsRares} pts)`,
                    type: 'QUOTA_RARE'
                };
            }
        }

        return { valid: true };
    }

    /**
     * Vérifie si on peut ajouter une amélioration
     */
    canAddAmelioration(liste, formation, ameliorationId) {
        const formationDef = this.findFormation(formation.formationId);
        const ameliorationDef = this.codex.ameliorations.find(a => a.id === ameliorationId);

        if (!ameliorationDef) return { valid: false, error: 'Amélioration introuvable' };

        // Limite par formation
        const limiteFormationResult = AmeliorationValidator.validateLimiteFormation(formation, ameliorationDef);
        if (!limiteFormationResult.valid) return limiteFormationResult;

        // Limite globale
        const limiteGlobaleResult = AmeliorationValidator.validateLimiteGlobale(liste, ameliorationDef);
        if (!limiteGlobaleResult.valid) return limiteGlobaleResult;

        // Unicité
        const uniqueResult = AmeliorationValidator.validateUnique(formation, ameliorationDef, this.codex);
        if (!uniqueResult.valid) return uniqueResult;

        // Exclusion mutuelle
        const exclusionResult = AmeliorationValidator.validateExclusion(formation, ameliorationDef, this.codex);
        if (!exclusionResult.valid) return exclusionResult;

        // Limite de nombre d'unités dans la formation
        if (ameliorationDef.max_unites_formation) {
            const totalUnites = formation.unites.reduce((total, unite) => {
                if (unite.remplace) return total;
                return total + (unite.nombre || 1);
            }, 0);

            if (totalUnites > ameliorationDef.max_unites_formation) {
                return {
                    valid: false,
                    error: `"${ameliorationDef.name}" nécessite une formation de ${ameliorationDef.max_unites_formation} unités maximum (${totalUnites} actuellement)`,
                    type: 'MAX_UNITES_FORMATION'
                };
            }
        }

        // Limite d'options de la formation (ou du groupe si non définie sur la formation)
        const groupe = this.codex.groupes.find(g => g.formations.some(fd => fd.id === formation.formationId));
        const limiteEffective = formationDef.limiteOptionFormation ?? groupe?.limiteOptionFormation ?? null;
        const limiteOptionsResult = FormationValidator.validateLimiteOptionFormation(
            formation, formationDef, this.codex.ameliorations, limiteEffective
        );
        if (!limiteOptionsResult.valid) return limiteOptionsResult;

        // Quota commissaire (règle spéciale)
        if (ameliorationDef.regle_quota) {
            const quotaResult = this.validateQuotaCommissaire(liste, ameliorationDef);
            if (!quotaResult.valid) return quotaResult;
        }

        return { valid: true };
    }

    validateQuotaCommissaire(liste, ameliorationDef) {
        const regle = this.codex.codex?.regles_speciales?.[ameliorationDef.regle_quota];
        if (!regle) return { valid: true };

        const pointsBase = liste.limitePts != null
            ? liste.limitePts
            : liste.formations.reduce((total, f) => {
                let cout = f.cout;
                f.ameliorations.forEach(a => {
                    const aDef = this.codex.ameliorations.find(am => am.id === a.ameliorationId);
                    if (aDef) cout += aDef.cout_par_unite ? aDef.cout * (a.quantite || 1) : aDef.cout;
                });
                return total + cout;
            }, 0);

        const quota = Math.ceil(pointsBase / regle.points_par_tranche) || 0;

        const utilises = liste.formations.reduce((total, f) => {
            const hasQuotaAmelio = f.ameliorations.some(a => {
                const aDef = this.codex.ameliorations.find(am => am.id === a.ameliorationId);
                return aDef?.regle_quota === ameliorationDef.regle_quota;
            });
            return total + (hasQuotaAmelio ? 1 : 0);
        }, 0);

        if (utilises >= quota) {
            return {
                valid: false,
                error: `Quota Commissaires atteint (${utilises}/${quota}). Ajoutez des Compagnies pour en débloquer davantage.`
            };
        }
        return { valid: true };
    }

    /**
     * Helpers
     */
    findFormation(formationId) {
        for (const groupe of this.codex.groupes) {
            const formation = groupe.formations.find(f => f.id === formationId);
            if (formation) return formation;
        }
        return null;
    }

    calculerPointsTotal(liste) {
        return liste.formations.reduce((total, formation) => {
            let cout = formation.cout;

            // Améliorations
            formation.ameliorations.forEach(amelio => {
                if (amelio.coutOverride !== undefined && amelio.coutOverride !== null) {
                    cout += amelio.coutOverride;
                    return;
                }
                const amelioDef = this.codex.ameliorations.find(a => a.id === amelio.ameliorationId);
                if (!amelioDef) return;
                cout += amelioDef.cout_par_unite ? amelioDef.cout * (amelio.quantite || 1) : amelioDef.cout;
            });

            return total + cout;
        }, 0);
    }
}