import React, { useState, useEffect } from 'react';
import {
    Container,
    Box,
    Typography,
    Card,
    CardContent,
    CardActions,
    Button,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogContentText,
    DialogActions,
    Grid,
    Accordion,
    AccordionSummary,
    AccordionDetails,
    Chip,
    Paper,
    Tooltip,
    IconButton,
    Alert
} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import PlayArrowIcon from '@mui/icons-material/PlayArrow';
import DeleteIcon from '@mui/icons-material/Delete';
import LoginIcon from '@mui/icons-material/Login';
import SaveIcon from '@mui/icons-material/Save';
import DevicesIcon from '@mui/icons-material/Devices';
import CloudIcon from '@mui/icons-material/Cloud';
import PublicIcon from '@mui/icons-material/Public';
import LockIcon from '@mui/icons-material/Lock';
import PeopleIcon from '@mui/icons-material/People';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { loadAllListes, deleteListe, loadPublicListes, toggleListePublique } from '../../services/listStorageService';
import LoginDialog from '../../components/LoginDialog';

function MesListesPage({ codexMap }) {
    const { user } = useAuth();
    const navigate = useNavigate();
    const [loginOpen, setLoginOpen] = useState(false);
    const [listes, setListes] = useState([]);
    const [listesPubliques, setListesPubliques] = useState([]);
    const [loading, setLoading] = useState(true);
    const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
    const [listeASupprimer, setListeASupprimer] = useState(null);
    const [togglingId, setTogglingId] = useState(null);

    useEffect(() => {
        setLoading(true);
        Promise.all([
            loadAllListes(user),
            loadPublicListes()
        ]).then(([mesListes, publiques]) => {
            mesListes.sort((a, b) => new Date(b.dateModification) - new Date(a.dateModification));
            setListes(mesListes);
            setListesPubliques(publiques);
        }).catch(err => {
            console.error('Erreur chargement listes:', err);
        }).finally(() => {
            setLoading(false);
        });
    }, [user]);

    const getCodexName = (codexId) => {
        const codex = codexMap[codexId];
        return codex?.codex?.name || codexId;
    };

    const getCodexColor = (codexId) => {
        const codex = codexMap[codexId];
        return codex?.codex?.color || '#4a7c59';
    };

    const handleCharger = (liste) => {
        navigate(`/builder/${liste.codexId}?loadListId=${liste.id}`);
    };

    const handleDemanderSuppression = (liste) => {
        setListeASupprimer(liste);
        setDeleteDialogOpen(true);
    };

    const handleConfirmerSuppression = async () => {
        if (listeASupprimer) {
            await deleteListe(listeASupprimer.id, user);
            setListes(prev => prev.filter(l => l.id !== listeASupprimer.id));
            setListesPubliques(prev => prev.filter(l => l.id !== listeASupprimer.id));
        }
        setDeleteDialogOpen(false);
        setListeASupprimer(null);
    };

    const [toggleError, setToggleError] = useState('');

    const handleTogglePublique = async (liste) => {
        if (!user) return;
        setTogglingId(liste.id);
        setToggleError('');
        const isPublic = !liste.publique;
        try {
            const updated = await toggleListePublique(liste, user, isPublic);
            setListes(prev => prev.map(l => l.id === updated.id ? updated : l));
            if (isPublic) {
                setListesPubliques(prev => {
                    const existing = prev.find(l => l.id === updated.id);
                    if (existing) return prev.map(l => l.id === updated.id ? updated : l);
                    return [...prev, updated];
                });
            } else {
                setListesPubliques(prev => prev.filter(l => l.id !== updated.id));
            }
        } catch (err) {
            setToggleError(err.message);
        } finally {
            setTogglingId(null);
        }
    };

    const formatDate = (dateStr) => {
        if (!dateStr) return '-';
        return new Date(dateStr).toLocaleDateString('fr-FR', {
            day: '2-digit',
            month: '2-digit',
            year: 'numeric',
            hour: '2-digit',
            minute: '2-digit'
        });
    };

    // Grouper les listes personnelles par codexId
    const listesParCodex = listes.reduce((acc, liste) => {
        const key = liste.codexId;
        if (!acc[key]) acc[key] = [];
        acc[key].push(liste);
        return acc;
    }, {});

    const codexIds = Object.keys(listesParCodex).sort((a, b) =>
        getCodexName(a).localeCompare(getCodexName(b))
    );

    // Grouper les listes publiques par codexId
    const publiquesParCodex = listesPubliques.reduce((acc, liste) => {
        const key = liste.codexId;
        if (!acc[key]) acc[key] = [];
        acc[key].push(liste);
        return acc;
    }, {});

    const codexIdsPubliques = Object.keys(publiquesParCodex).sort((a, b) =>
        getCodexName(a).localeCompare(getCodexName(b))
    );

    if (loading) {
        return (
            <Container maxWidth="lg" sx={{ py: 4 }}>
                <Typography>Chargement...</Typography>
            </Container>
        );
    }

    if (!user) {
        return (
            <Container maxWidth="sm" sx={{ py: 6 }}>
                <Paper elevation={3} sx={{ p: 4, borderRadius: 3, textAlign: 'center' }}>
                    <Typography variant="h5" fontWeight="bold" gutterBottom>
                        Sauvegardez vos listes
                    </Typography>
                    <Typography variant="body1" color="text.secondary" sx={{ mb: 3 }}>
                        Créez un compte gratuit pour profiter de toutes les fonctionnalités.
                    </Typography>

                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mb: 4, textAlign: 'left' }}>
                        {[
                            { icon: <SaveIcon color="primary" />, text: 'Sauvegardez vos listes d\'armée' },
                            { icon: <CloudIcon color="primary" />, text: 'Accédez-y depuis n\'importe où' },
                            { icon: <DevicesIcon color="primary" />, text: 'Synchronisation multi-appareils' },
                        ].map(({ icon, text }) => (
                            <Box key={text} sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                                {icon}
                                <Typography variant="body2">{text}</Typography>
                            </Box>
                        ))}
                    </Box>

                    <Button
                        variant="contained"
                        size="large"
                        fullWidth
                        startIcon={<LoginIcon />}
                        onClick={() => setLoginOpen(true)}
                        sx={{ fontWeight: 'bold', borderRadius: 2, textTransform: 'none', mb: 1 }}
                    >
                        Se connecter / S'inscrire
                    </Button>
                    <Typography variant="caption" color="text.secondary">
                        Gratuit — aucune carte bancaire requise
                    </Typography>
                </Paper>
                <LoginDialog open={loginOpen} onClose={() => setLoginOpen(false)} />
            </Container>
        );
    }

    const renderListeCard = (liste, color, isOwner) => (
        <Grid item xs={12} sm={6} md={4} key={liste.id}>
            <Card variant="outlined" sx={{ borderLeft: `4px solid ${color}` }}>
                <CardContent sx={{ pb: 0, pt: 1.5, px: 1.5 }}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                        <Typography variant="subtitle2" noWrap sx={{ fontWeight: 'bold', flex: 1 }}>
                            {liste.nom}
                        </Typography>
                        {liste.publique && (
                            <Tooltip title="Liste publique">
                                <PublicIcon sx={{ fontSize: 14, color: 'success.main', flexShrink: 0 }} />
                            </Tooltip>
                        )}
                    </Box>
                    <Typography variant="body2" color="primary" sx={{ mt: 0.5 }}>
                        {liste.totalPoints || 0} pts · {liste.formations?.length || 0} formations
                    </Typography>
                    <Typography variant="caption" color="textSecondary" display="block">
                        {isOwner ? formatDate(liste.dateModification) : (liste.ownerDisplayName || 'Anonyme')}
                    </Typography>
                </CardContent>
                <CardActions sx={{ pt: 0, px: 1 }}>
                    <Button
                        size="small"
                        startIcon={<PlayArrowIcon />}
                        onClick={() => handleCharger(liste)}
                    >
                        Charger
                    </Button>
                    {isOwner && (
                        <>
                            <Tooltip title={liste.publique ? 'Rendre privée' : 'Rendre publique'}>
                                <IconButton
                                    size="small"
                                    color={liste.publique ? 'success' : 'default'}
                                    disabled={togglingId === liste.id}
                                    onClick={() => handleTogglePublique(liste)}
                                >
                                    {liste.publique ? <PublicIcon fontSize="small" /> : <LockIcon fontSize="small" />}
                                </IconButton>
                            </Tooltip>
                            <Button
                                size="small"
                                color="error"
                                startIcon={<DeleteIcon />}
                                onClick={() => handleDemanderSuppression(liste)}
                            >
                                Supprimer
                            </Button>
                        </>
                    )}
                </CardActions>
            </Card>
        </Grid>
    );

    return (
        <Container maxWidth="lg" sx={{ py: 2 }}>
            <Typography variant="h5" gutterBottom sx={{ mb: 2 }}>
                Mes listes
            </Typography>

            {listes.length === 0 ? (
                <Box sx={{ textAlign: 'center', py: 4 }}>
                    <Typography variant="h6" color="textSecondary" gutterBottom>
                        Aucune liste sauvegardée
                    </Typography>
                    <Typography color="textSecondary">
                        Construisez une liste dans le builder puis sauvegardez-la pour la retrouver ici.
                    </Typography>
                </Box>
            ) : (
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1, mb: 3 }}>
                    {codexIds.map(codexId => {
                        const color = getCodexColor(codexId);
                        const listesCodex = listesParCodex[codexId];
                        return (
                            <Accordion key={codexId} disableGutters>
                                <AccordionSummary
                                    expandIcon={<ExpandMoreIcon sx={{ color: 'white' }} />}
                                    sx={{
                                        backgroundColor: color,
                                        color: 'white',
                                        minHeight: 48,
                                        '&.Mui-expanded': { minHeight: 48 },
                                        '& .MuiAccordionSummary-content': { my: 1 }
                                    }}
                                >
                                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                        <Typography variant="subtitle1" sx={{ fontWeight: 'bold' }}>
                                            {getCodexName(codexId)}
                                        </Typography>
                                        <Chip
                                            label={listesCodex.length}
                                            size="small"
                                            sx={{ backgroundColor: 'rgba(255,255,255,0.3)', color: 'white', height: 20, fontSize: '0.7rem' }}
                                        />
                                    </Box>
                                </AccordionSummary>
                                <AccordionDetails sx={{ p: 1.5 }}>
                                    <Grid container spacing={1}>
                                        {listesCodex.map(liste => renderListeCard(liste, color, true))}
                                    </Grid>
                                </AccordionDetails>
                            </Accordion>
                        );
                    })}
                </Box>
            )}

            {toggleError && (
                <Alert severity="error" sx={{ mb: 2 }} onClose={() => setToggleError('')}>
                    {toggleError}
                </Alert>
            )}

            {/* ========== LISTES PUBLIQUES ========== */}
            {listesPubliques.length > 0 && (
                <>
                    <Typography variant="h5" gutterBottom sx={{ mb: 2 }}>
                        Listes publiques de la communauté
                    </Typography>
                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                        {codexIdsPubliques.map(codexId => {
                            const color = getCodexColor(codexId);
                            const listesCodex = publiquesParCodex[codexId];
                            return (
                                <Accordion key={`pub-${codexId}`} disableGutters>
                                    <AccordionSummary
                                        expandIcon={<ExpandMoreIcon sx={{ color: 'white' }} />}
                                        sx={{
                                            backgroundColor: color,
                                            color: 'white',
                                            minHeight: 48,
                                            '&.Mui-expanded': { minHeight: 48 },
                                            '& .MuiAccordionSummary-content': { my: 1 }
                                        }}
                                    >
                                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                            <PeopleIcon sx={{ fontSize: 18 }} />
                                            <Typography variant="subtitle1" sx={{ fontWeight: 'bold' }}>
                                                {getCodexName(codexId)}
                                            </Typography>
                                            <Chip
                                                label={listesCodex.length}
                                                size="small"
                                                sx={{ backgroundColor: 'rgba(255,255,255,0.3)', color: 'white', height: 20, fontSize: '0.7rem' }}
                                            />
                                        </Box>
                                    </AccordionSummary>
                                    <AccordionDetails sx={{ p: 1.5 }}>
                                        <Grid container spacing={1}>
                                            {listesCodex.map(liste =>
                                                renderListeCard(liste, color, user?.uid === liste.ownerUid)
                                            )}
                                        </Grid>
                                    </AccordionDetails>
                                </Accordion>
                            );
                        })}
                    </Box>
                </>
            )}

            <Dialog open={deleteDialogOpen} onClose={() => setDeleteDialogOpen(false)}>
                <DialogTitle>Supprimer la liste</DialogTitle>
                <DialogContent>
                    <DialogContentText>
                        Voulez-vous vraiment supprimer la liste "{listeASupprimer?.nom}" ?
                        Cette action est irréversible.
                    </DialogContentText>
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setDeleteDialogOpen(false)}>Annuler</Button>
                    <Button onClick={handleConfirmerSuppression} color="error">Supprimer</Button>
                </DialogActions>
            </Dialog>
        </Container>
    );
}

export default MesListesPage;
