/**
 * Validations au niveau des formations
 */
export class FormationValidator {

    /**
     * Vérifie la limite globale d'une formation
     */
    static validateFormationLimite(liste, formationDef) {
        if (!formationDef.FormationLimite) return { valid: true };

        const count = liste.formations.filter(
            f => f.formationId === formationDef.id
        ).length;

        if (count >= formationDef.FormationLimite) {
            return {
                valid: false,
                error: `Maximum ${formationDef.FormationLimite} ${formationDef.name} autorisé(es)`,
                type: 'FORMATION_LIMITE'
            };
        }

        return { valid: true };
    }

    /**
     * Vérifie le nombre min de formations dans un groupe
     */
    static validateMinFormations(liste, codex, groupe) {
        const results = [];

        // Minimum global du groupe
        if (groupe.min_formations) {
            const count = liste.formations.filter(f => {
                return groupe.formations.some(gf => gf.id === f.formationId);
            }).length;

            if (count < groupe.min_formations) {
                results.push({
                    valid: false,
                    error: `Au moins ${groupe.min_formations} formation(s) de type "${groupe.name}" requise(s)`,
                    type: 'MIN_FORMATIONS',
                    blocking: true
                });
            }
        }

        // Minimum par formation individuelle
        groupe.formations.forEach(formationDef => {
            if (!formationDef.FormationMinimum) return;

            const count = liste.formations.filter(f => f.formationId === formationDef.id).length;
            if (count < formationDef.FormationMinimum) {
                results.push({
                    valid: false,
                    error: `Au moins ${formationDef.FormationMinimum} "${formationDef.name}" requis(e) dans l'armée`,
                    type: 'MIN_FORMATIONS',
                    blocking: true
                });
            }
        });

        if (results.length > 0) return results[0];
        return { valid: true };
    }

    /**
     * Vérifie le nombre max d'améliorations d'une formation
     * limite : valeur explicite (surcharge formationDef.limiteOptionFormation)
     */
    static validateLimiteOptionFormation(formation, formationDef, ameliorationsDefs = [], limite = null) {
        const effectiveLimite = limite ?? formationDef.limiteOptionFormation;
        if (!effectiveLimite) return { valid: true };

        // Compte les améliorations hors IsNotOption (transports, etc.)
        const count = formation.ameliorations.filter(amelio => {
            const amelioDef = ameliorationsDefs.find(a => a.id === amelio.ameliorationId);
            return !amelioDef?.IsNotOption;
        }).length;

        if (count >= effectiveLimite) {
            return {
                valid: false,
                error: `Maximum ${effectiveLimite} amélioration(s) pour cette formation`,
                type: 'LIMITE_OPTIONS'
            };
        }

        return { valid: true };
    }
}